// 由 tools/build.js 生成，请勿直接编辑。
window.GAME_DATA = {"meta":{"title":"在海风消失之前","chars":{"林澈":{"id":"rinche","color":"#9fb8cf","sprite":false},"美咲":{"id":"misaki","color":"#e6a8c0","sprite":true},"玲奈":{"id":"reina","color":"#8fa8d8","sprite":true},"阳葵":{"id":"himari","color":"#e8b45c","sprite":true},"乃爱":{"id":"noa","color":"#a8a0d8","sprite":true},"遥":{"id":"haruka","color":"#8cc8c0","sprite":true}}},"main":[{"t":"ch","title":"序章　九月，风从来处吹来","ln":20},{"t":"bg","id":"station_year","ln":24},{"t":"n","x":"列车驶过弯道时，我在玻璃里看见自己的脸。与去年那个回到海陵的转学生相比，眉眼并没有改变多少。只是列车减速、站名亮起，我没有再生出逃到下一站的念头。车门一开，风夹着盐味涌进来，仿佛有人把一整年的日子摊在面前：纪念馆开幕、期末考、朋友们的生日，还有上个月五个人在防波堤上分吃的一袋热栗子。","ln":27},{"t":"d","w":"林澈","x":"这座城的风，真的连早上都不肯睡。","ln":29},{"t":"d","w":"美咲","x":"因为有人明明说会提前十分钟到，结果现在才下车。","ln":31},{"t":"n","x":"美咲站在检票口，耳边仍是那枚白花发夹。去年她在这里问我是不是真的回来了；如今她手里没有迎接归人的标语，只有两张去学校的车票。","ln":34},{"t":"d","w":"林澈","x":"我确实提前十分钟到站了。列车晚点属于铁路部门。","ln":36},{"t":"d","w":"美咲","x":"你把责任分得很清楚嘛。","ln":37},{"t":"d","w":"林澈","x":"从去年的事故说明会学会的。","ln":38},{"t":"n","x":"她没有因那个词而变色，只把另一张票递给我。以前我们连它都不敢说，现在它只是人生中一个具体的事件，有来由，有后果，也有许多继续发生在后面的日子。","ln":41},{"t":"d","w":"美咲","x":"今天公布毕业纪念册的征稿题目。","ln":43},{"t":"d","w":"林澈","x":"让我猜，《闪耀的青春》？","ln":44},{"t":"d","w":"美咲","x":"不是。《写给离开之后的我们》。","ln":45},{"t":"d","w":"林澈","x":"写得出来吗？","ln":46},{"t":"d","w":"美咲","x":"先写再说。你以前不是说，计划可以修改？","ln":47},{"t":"n","x":"那句话分明是玲奈说的。她把它记住，又自然地用在自己的生活里。站台的广播催我们上车，车窗映出并肩的身影。美咲看着玻璃，忽然问：","ln":50},{"t":"d","w":"美咲","x":"林澈，毕业以后，你有没有想过离开海陵？","ln":52},{"t":"n","x":"我想说「还早」。可是书包里装着父亲昨夜寄来的申请资料。纸角隔着布料抵住我的背，好像一句迟早要说出口的话。","ln":55},{"t":"d","w":"林澈","x":"想过。还没想明白。","ln":57},{"t":"d","w":"美咲","x":"嗯。","ln":58},{"t":"d","w":"林澈","x":"你呢？","ln":59},{"t":"d","w":"美咲","x":"我也是。","ln":60},{"t":"n","x":"列车驶出车站。两个人谁也没有追问，却都知道对方没有说完。","ln":63},{"t":"ch","title":"第一章　毕业纪念册不负责回答未来","ln":65},{"t":"bg","id":"classroom","ln":69},{"t":"n","x":"黑板右上角挂着距离毕业还有一百七十二天的纸牌。有人每天撕掉一页，有人假装不看；时间并不需要我们承认，仍然一页一页地薄下去。班主任把一叠升学调查表放在讲台上，纸张落下的声音，竟比上课铃还整齐。","ln":72},{"t":"d","w":"班主任","x":"志愿只是目前的想法，可以修改。但空白不能成为最后的答案。下周前交来。","ln":74},{"t":"n","x":"我的表格第一栏写了「海陵大学人文信息学系」，第二栏写了一半又划掉。父亲寄来的海外项目需要语言考试、作品集和面试；我对城市档案、口述历史的兴趣，确实能在那里得到训练。可「想去」与「应该去」，像两根极细的线，交在一起便很难分清。","ln":77},{"t":"d","w":"阳葵","x":"林澈，你怎么把第二志愿写成一团海藻？","ln":79},{"t":"d","w":"林澈","x":"抽象艺术。","ln":80},{"t":"d","w":"阳葵","x":"我看是拖延的具象艺术。","ln":81},{"t":"d","w":"玲奈","x":"说得有道理。给他一周，作品还会扩散成整张纸。","ln":82},{"t":"d","w":"林澈","x":"前会长也开始参与围攻？","ln":83},{"t":"d","w":"玲奈","x":"我卸任了，终于有空诚实评价。","ln":84},{"t":"n","x":"乃爱把一本旧星图册放到桌上。封面上有遥亲手写的小字：「看不见的星仍在那里」。纪念馆请毕业班整理一份导览，作为新学期给后辈的资料。对我们而言，这项工作再普通不过：查阅、校对、申请使用教室，像去年办过的任何活动。","ln":87},{"t":"d","w":"乃爱","x":"馆方问我们，能不能各写一段给一年后的自己。","ln":89},{"t":"d","w":"阳葵","x":"一年后的我肯定比现在跑得快。","ln":90},{"t":"d","w":"玲奈","x":"你上个月才说，成绩不是衡量你的唯一方式。","ln":91},{"t":"d","w":"阳葵","x":"是啊。我想跑得快，不代表跑不快就完蛋。","ln":92},{"t":"d","w":"乃爱","x":"进步。请把这句话写进去。","ln":93},{"t":"n","x":"阳葵抢走她的笔，在纸上画了一条跑道，又画一颗歪斜的星。玲奈皱着眉说布局不合规范，美咲小心地把那颗星描圆。我看着她们，想起去年在旧学生会室熬夜整理事故记录的情形。那时我们以为只要把过去放回它本来的位置，未来就会自然出现。如今才明白，未来不会像失物招领一样，等我们去认领。","ln":96},{"t":"c","o":[{"x":"先填一个最稳妥的答案，免得父亲担心。","i":196},{"x":"把两个真正想考虑的方向都写上，并注明尚待决定。","i":198},{"x":"暂时交白卷，等别人给出建议。","i":200}],"ln":98},{"t":"bg","id":"observatory","ln":104},{"t":"n","x":"纪念馆没有把旧天文台的损坏从叙述中擦掉。楼梯旁陈列着一段拆下的旧栏杆，说明牌写清楚报修与延期维修的日期。馆里的新扶手牢固、朴素，不承担象征意义，只负责保护来访的人。这一点，倒让我觉得安心。","ln":107},{"t":"d","w":"乃爱","x":"馆长想把旧栏杆移到储藏室。怕参观的人看了不舒服。","ln":109},{"t":"d","w":"玲奈","x":"历史说明不该只挑好看的部分。可以调整摆放位置，不能删掉事实。","ln":110},{"t":"d","w":"美咲","x":"但遥学姐也有权决定她是否愿意天天被人指着事故介绍。","ln":111},{"t":"n","x":"大家安静下来。我们已经习惯替真相争一个位置，却差一点又忘了真相中的人也有今天。","ln":114},{"t":"d","w":"乃爱","x":"我今晚问她。让她自己说。","ln":116},{"t":"d","w":"阳葵","x":"她也可以说「别问我」。","ln":117},{"t":"d","w":"乃爱","x":"对。","ln":118},{"t":"n","x":"玲奈在清单上划去「替遥决定展陈方案」几个字，重新写成「征询当事人意见」。她的笔尖顿了一瞬，然后把清单递给乃爱。平常不过的动作，像把一扇门真正打开。","ln":121},{"t":"ch","title":"第二章　五张车票与一张没有寄出的表","ln":123},{"t":"bg","id":"student_council","ln":127},{"t":"n","x":"新一届学生会已经接手这里。玲奈借到房间两小时，说是为了整理纪念馆导览稿；阳葵带来五份炸鸡、四瓶汽水和一瓶无糖茶。她记得玲奈喝咖啡时偷偷加糖，却还是每次都假装按「健康」标准采购。","ln":130},{"t":"d","w":"阳葵","x":"我要宣布新闻。北陆体育大学的教练看了我上个月的比赛录像，邀请我参加冬季选拔。","ln":132},{"t":"d","w":"美咲","x":"真的？恭喜！","ln":133},{"t":"d","w":"玲奈","x":"你和康复医生确认训练安排了吗？","ln":134},{"t":"d","w":"阳葵","x":"确认过。两周后复诊，训练量不能自己加。","ln":135},{"t":"d","w":"林澈","x":"你居然先说这句。","ln":136},{"t":"d","w":"阳葵","x":"我会长大，你也应该试试。","ln":137},{"t":"n","x":"阳葵笑得响亮，只有把邀请邮件推过来时，指尖轻轻敲着桌面。那所学校离海陵很远，专业队一年有九个月在训练或比赛。比距离更难说出口的，是「去了之后还会不会快乐」。","ln":140},{"t":"d","w":"美咲","x":"我也有一件事。东京青叶大学文学部给了我推荐面试资格。","ln":142},{"t":"d","w":"阳葵","x":"你们是约好今天公布吗？","ln":143},{"t":"d","w":"美咲","x":"昨天才收到邮件。我想先确定它是真的。","ln":144},{"t":"d","w":"玲奈","x":"邮件抬头和招生办公室电话都能核对。我可以帮你确认。","ln":145},{"t":"d","w":"美咲","x":"已经确认过了。这次我自己打的电话。","ln":146},{"t":"n","x":"她说得轻，却没有缩回眼睛。旧时那个总怕麻烦别人的美咲，已经能独自问清楚一件属于她的事。","ln":149},{"t":"d","w":"玲奈","x":"那么我也宣布。海陵大学文学部提前招生，我通过了材料初审。","ln":151},{"t":"d","w":"阳葵","x":"三个人！乃爱呢？","ln":152},{"t":"d","w":"乃爱","x":"我报名了京都的科学传播项目体验周。不代表转学，也不代表决定去那里读大学。","ln":153},{"t":"d","w":"阳葵","x":"你回答得好像提前看过我要问什么。","ln":154},{"t":"d","w":"乃爱","x":"你去年问过八次。","ln":155},{"t":"n","x":"四道目光最后落到我身上。我把父亲的信从书包拿出来。纸很平，边缘却被我反复捏软了。","ln":158},{"t":"d","w":"林澈","x":"国外有个城市记忆研究项目，招预科学生。父亲说，如果我愿意申请，他能帮我联系学校。截止在冬天。","ln":160},{"t":"d","w":"美咲","x":"你愿意吗？","ln":161},{"t":"d","w":"林澈","x":"我喜欢那个方向。也喜欢海陵的档案馆。我没想好。","ln":162},{"t":"d","w":"玲奈","x":"两个选项都是真实的，就先不要把犹豫叫作软弱。","ln":163},{"t":"d","w":"阳葵","x":"可以同时准备，等到真正必须选时再选。","ln":164},{"t":"d","w":"乃爱","x":"时间线我来列。你们的人类申请材料太多。","ln":165},{"t":"d","w":"阳葵","x":"又说自己不是人类！","ln":166},{"t":"n","x":"笑声落下后，美咲把五张空白卡片推到桌中央，说每人写下一个未来不想丢掉的东西。阳葵写「喜欢跑步的原因」。玲奈写「选择之后继续生活的勇气」。乃爱写「可以改变的自己」。美咲先写「说真话」，想了想，又在下面添上「以及听真话」。我写得最慢，只写下「这些人的电话号码」。","ln":169},{"t":"d","w":"美咲","x":"你这个像通讯录备份。","ln":171},{"t":"d","w":"林澈","x":"很重要。有人当年换了号码，造成严重后果。","ln":172},{"t":"n","x":"她看我一眼，没有替我把玩笑收场，而是问：","ln":175},{"t":"d","w":"美咲","x":"那第二行呢？","ln":177},{"t":"n","x":"我在卡上补了三个字：「我自己」。窗外传来晚课的铃声。五个人写的都不是目的地，像是对远行的人而言，方向也许要从行李里找。","ln":180},{"t":"ch","title":"第三章　不寄出的信也有重量","ln":183},{"t":"bg","id":"library","ln":187},{"t":"n","x":"纪念馆的导览稿需要一张去年修订的事故记录副本。我到图书馆查校史资料，美咲在那里整理毕业纪念册投稿。她的笔记本夹着一篇题为《岛屿之间》的散文：写人如何隔海望见另一座岛的灯，不把灯光误认为桥。她的句子比从前更大胆，写海风会使眼睛疼，也写灯终有熄灭的时候。","ln":190},{"t":"d","w":"林澈","x":"这一句很好。","ln":192},{"t":"d","w":"美咲","x":"哪一句？","ln":193},{"t":"d","w":"林澈","x":"「我可以想念岸的形状，也可以学会自己掌舵。」","ln":194},{"t":"d","w":"美咲","x":"你从背后看别人草稿，礼貌程度下降了。","ln":195},{"t":"d","w":"林澈","x":"抱歉。我把那句忘掉。","ln":196},{"t":"d","w":"美咲","x":"不用。你觉得好就好。","ln":197},{"t":"n","x":"她合上笔记本，拇指停在页边。东京那所大学的推荐面试，要求提交一篇原创作品。她选择了这一篇，却迟迟没有把最后一段写完。","ln":200},{"t":"d","w":"林澈","x":"你在等结尾？","ln":202},{"t":"d","w":"美咲","x":"也许在等一个答案。我写到出发那天，忽然不知道船上那个人会不会害怕。","ln":203},{"t":"d","w":"林澈","x":"当然会。不会害怕的出发反而有点可疑。","ln":204},{"t":"d","w":"美咲","x":"那是不是要等不怕了再去？","ln":205},{"t":"d","w":"林澈","x":"如果每个人都这么等，海陵港会空很多年。","ln":206},{"t":"n","x":"她笑了，却没告诉我她在草稿背面写过另一段话：「如果我去东京，他会不会以为我也要像当年的他一样突然离开？」我也没有拿出父亲的项目材料。两个以为自己懂得沟通的人，在这张桌子上各留了一封没有寄出的信。","ln":209},{"t":"c","o":[{"x":"问美咲，面试资料中最让她期待的是什么。","i":202},{"x":"向美咲保证，毕业以后大家一定还会和现在一样。","i":204},{"x":"只说「加油」，立刻去办自己的事。","i":206}],"ln":211},{"t":"bg","id":"street_dusk","ln":217},{"t":"n","x":"玲奈约我看文学部的资料室。她不是来打听父亲认可哪一个专业，而是要确认自己是否愿意在这里读四年。母亲那天在医院做例行复查，父亲已经答应陪同。玲奈嘴上说「安排合理」，却每隔十分钟看一次手机。","ln":220},{"t":"d","w":"林澈","x":"你可以打电话问。","ln":222},{"t":"d","w":"玲奈","x":"复查还没结束，问也不会加快报告。","ln":223},{"t":"d","w":"林澈","x":"有些电话不是为了加快报告。","ln":224},{"t":"n","x":"玲奈停在馆藏目录前。以前，她会把担心卷成一张工整的待办表，等到所有事项处理妥当才允许自己疲倦。如今她直接拨了电话。那头母亲说一切顺利，还抱怨医院的茶太淡；玲奈听了三分钟，终于不再盯着手机。","ln":227},{"t":"d","w":"玲奈","x":"她说让我买一块草莓蛋糕回去。","ln":229},{"t":"d","w":"林澈","x":"你呢？","ln":230},{"t":"d","w":"玲奈","x":"我也想吃。","ln":231},{"t":"d","w":"林澈","x":"这句话有进步。","ln":232},{"t":"n","x":"资料室里，一位老师讲解海陵地方文学的口述史项目。玲奈听得很专注，连提问也不是关于通过率，而是关于受访者有权在出版前撤回哪些内容。她的眼睛亮起来，像第一次允许自己把知识当成兴趣，而不是下一道考题。会后她把项目简章放进包里，没有立刻计算录取概率。","ln":235},{"t":"d","w":"玲奈","x":"我想读这个。","ln":237},{"t":"d","w":"林澈","x":"我听见了。","ln":238},{"t":"d","w":"玲奈","x":"你不问理由？","ln":239},{"t":"d","w":"林澈","x":"你说想，我先相信。","ln":240},{"t":"n","x":"她把简章拿出来，指给我看第三页的一项田野课程，讲得越来越快。信任她的选择，并不意味着不听她解释；恰好相反，我有足够耐心听完那些细节。","ln":243},{"t":"bg","id":"playground","ln":245},{"t":"n","x":"阳葵的跑鞋在地面上敲出均匀的声响。她的教练把训练分成短距离、低强度和休息日；她每一次想多跑，都要先把念头写在日志里，第二天再看是否真的必要。日志封面画着一只慢吞吞的海龟，是乃爱送的。","ln":248},{"t":"d","w":"阳葵","x":"今天不计时，陪我跑一圈。","ln":250},{"t":"d","w":"林澈","x":"你说的一圈，是我的一圈还是你的？","ln":251},{"t":"d","w":"阳葵","x":"同一条跑道还有两种长度？","ln":252},{"t":"d","w":"林澈","x":"配速不同，痛苦的长度不同。","ln":253},{"t":"n","x":"我们从起点并肩。她故意压慢脚步，到了半圈却望向跑道尽头，仿佛那里站着一支看不见的队伍。北陆体育大学的邀请在她口袋里。她不再把停下当成失败，仍然不知道要不要让跑步成为职业的一部分。","ln":256},{"t":"d","w":"阳葵","x":"假如我被选上，训练量会变大。比赛也会多。","ln":258},{"t":"d","w":"林澈","x":"教练知道你的伤史吗？","ln":259},{"t":"d","w":"阳葵","x":"知道。他们要我带复诊记录，做专项评估。没有人保证一定收我。","ln":260},{"t":"d","w":"林澈","x":"这听起来很认真。","ln":261},{"t":"d","w":"阳葵","x":"所以更吓人。以前我只要说「等腿好了再想」。腿好了，借口也好了。","ln":262},{"t":"n","x":"她在终点前主动停下。河水被夕阳照得像一条熔化的铜线。她告诉我，上周她去运动康复中心做志愿者，替一个受伤的小学生记训练数据。那孩子没有问她拿过多少奖牌，只问为什么脚会疼。她第一次发现，自己喜欢的不止跑过别人，也喜欢帮别人找到能继续跑的方法。","ln":265},{"t":"d","w":"阳葵","x":"我能不能一边认真训练，一边学这个？","ln":267},{"t":"d","w":"林澈","x":"可以把这个问题拿去问那所学校。答案比我们猜的可靠。","ln":268},{"t":"d","w":"阳葵","x":"你今天居然没有说「无论怎样我都等你」。","ln":269},{"t":"d","w":"林澈","x":"那句话留给需要的时候。","ln":270},{"t":"d","w":"阳葵","x":"行。你省着点用。","ln":271},{"t":"bg","id":"observatory","ln":273},{"t":"n","x":"乃爱试播遥新录的导览。遥的声音从扬声器里传出，清楚地介绍星图设备如何用齿轮模拟四季星空。她没有提事故，也没有提自己。放映结束后，乃爱没有立刻关灯。圆顶上模拟的夏季星座缓慢移向西方，像有人轻轻挪动一张旧照片。","ln":276},{"t":"d","w":"乃爱","x":"姐姐昨天想起一句话。","ln":278},{"t":"d","w":"林澈","x":"什么？","ln":279},{"t":"d","w":"乃爱","x":"她说，那年她教过一个男生辨认天鹅座。她不确定那个男生是不是你。","ln":280},{"t":"d","w":"林澈","x":"我也不确定。我记得你姐姐告诉我，星星不会因为云遮住就消失。但天鹅座，也许是我后来自己在书上学的。","ln":281},{"t":"d","w":"乃爱","x":"她不需要你替她确认。","ln":282},{"t":"d","w":"林澈","x":"嗯。她可以慢慢想，也可以不想。","ln":283},{"t":"n","x":"乃爱点头，却没有靠过来。她曾以为姐姐遗失的记忆像一个空座位，任何人只要坐上去，都会使她的存在显得多余。现在记忆有了边缘模糊的影子，她反而更难说明自己的心情。","ln":286},{"t":"d","w":"乃爱","x":"我申请京都的体验周，想看看科学馆怎样给小孩子讲星图。","ln":288},{"t":"d","w":"林澈","x":"你喜欢做这个？","ln":289},{"t":"d","w":"乃爱","x":"我喜欢他们听明白时突然抬头的表情。以前我只会纠正错误，不太会等人理解。","ln":290},{"t":"d","w":"林澈","x":"去年你就会。打雷那天，美咲说可以一起等，你真的等了。","ln":291},{"t":"d","w":"乃爱","x":"那天我主要是没地方躲。","ln":292},{"t":"d","w":"林澈","x":"对，你绝对没有握住阳葵的袖子。","ln":293},{"t":"d","w":"乃爱","x":"如果你向她求证，我会否认。","ln":294},{"t":"n","x":"她语气平平，嘴角却动了一下。我们在假星空下坐了一会儿。真正的夜空被云遮住，并不因此失去存在的权利。人也一样；一个人不必靠另一个人的记忆来证明自己是谁。","ln":297},{"t":"ch","title":"第四章　十月的两次谈话","ln":299},{"t":"bg","id":"room","ln":303},{"t":"n","x":"父亲从出差地回来，行李轮在地板上滚过。两年前搬离海陵时，我们曾把彼此的沉默误认作体贴。如今他在饭桌上问我是否收到预科项目资料，我没有把文件推回去，也没有立刻说好。","ln":306},{"t":"d","w":"父亲","x":"我能帮你约一位项目毕业生。你可以问费用、课程和之后怎么升学。","ln":308},{"t":"d","w":"林澈","x":"谢谢。我想知道你为什么推荐它。","ln":309},{"t":"d","w":"父亲","x":"你去年做事故记录时，后来又去查了海陵城建档案。你对这些东西有兴趣。这个项目教口述史和数字保存，与你相合。","ln":310},{"t":"d","w":"林澈","x":"我原以为你只是想让我离开海陵。","ln":311},{"t":"d","w":"父亲","x":"我也曾这么想。那时我以为换一个地方，你就不会天天想起天文台。我做错了。","ln":312},{"t":"n","x":"这句话说得平实，没有晚来的父子拥抱。我却忽然想起，事故后的父亲同样不知道怎么安慰人。他把一切能搬走的都搬走了，包括我们的住址，却没能搬走我脑子里的雨声。","ln":315},{"t":"d","w":"林澈","x":"这一次，我会自己选。申请它，不表示我一定去；留在海陵，也不是为了证明我敢面对过去。","ln":317},{"t":"d","w":"父亲","x":"好。材料和预算我会列清楚。最后那栏由你填。","ln":318},{"t":"n","x":"夜里我打开窗，听见远处港口轮船的鸣笛。父亲把一张便条放在书桌上，上面不是「一定要抓住机会」，而是毕业生的联络时间、项目的奖学金条件，以及一句很轻的「回绝也可以」。我把便条压在志愿表下。两张纸叠在一起，反而没那么重了。","ln":321},{"t":"bg","id":"street_dusk","ln":323},{"t":"d","w":"阳葵","x":"通知！毕业纪念馆导览会定在十二月第一个星期六。","ln":325},{"t":"d","w":"玲奈","x":"那天与校内模拟面试冲突。导览会下午开始，可以调整。","ln":326},{"t":"d","w":"乃爱","x":"姐姐愿意录音，不愿在现场讲事故。请照她说的做。","ln":327},{"t":"d","w":"美咲","x":"稿子我来改，写她想讲的星图。","ln":328},{"t":"d","w":"林澈","x":"我负责旧资料核对。还有，今天和我爸谈过申请了。","ln":329},{"t":"d","w":"阳葵","x":"结果？","ln":330},{"t":"d","w":"林澈","x":"没有结果，只有一张时间表。","ln":331},{"t":"d","w":"玲奈","x":"时间表已经很好。","ln":332},{"t":"d","w":"乃爱","x":"至少比消失好。","ln":333},{"t":"d","w":"美咲","x":"我也有事情想和大家说。面试定在下个月。我会去。","ln":334},{"t":"n","x":"聊天框里出现了四个「正在输入」。谁也没有用「那你毕业后一定去东京了」替美咲把尚未发生的事说完。阳葵发了一张夸张的加油表情，玲奈发面试准备清单，乃爱发东京科学馆地图。我打字：「你回来以后想吃什么？」美咲回：「海陵站旁边那家蛋包饭。面试前也可以陪我吃一次。」我答应了。","ln":337},{"t":"c","o":[{"x":"「无论你们去哪，我都会祝福。」","i":208},{"x":"「我为你们高兴，也会舍不得；有空时听我说说。」","i":210},{"x":"「现在说这些太早，等结果出来再谈。」","i":212}],"ln":339},{"t":"ch","title":"第五章　导览会的空白页","ln":345},{"t":"bg","id":"observatory","ln":349},{"t":"n","x":"海陵很少下雪，冬天多半只是把海风吹得更硬。馆门口的新指示牌印着五个人合作完成的导览图。旧栏杆留在一面不显眼却清楚可见的墙上，说明牌经过遥本人审阅，文字到「修订记录」为止；她现在的康复情况、住处和私人生活都没有被放上去。","ln":352},{"t":"d","w":"馆长","x":"今天有三组初中生预约。你们负责星图室和档案墙。","ln":354},{"t":"d","w":"阳葵","x":"如果他们问事故呢？","ln":355},{"t":"d","w":"乃爱","x":"按牌上的事实回答。不要讲没获得同意的细节。","ln":356},{"t":"d","w":"玲奈","x":"如果问超出范围，可以说不知道。","ln":357},{"t":"d","w":"林澈","x":"我去年最需要学的就是这句。","ln":358},{"t":"n","x":"第一组学生比预期更活跃。他们仰头追着星图的光走，问冬季星座为何在夏天的天空里看不见。乃爱弯腰，把手电筒照在球面模型上，慢慢让他们自己转动。遥的录音在一旁解释机械齿轮，姐姐和妹妹各说各的，声音没有相互覆盖。\n\n第二组学生经过档案墙时，一个女孩停在修订记录前。","ln":361},{"t":"d","w":"女孩","x":"如果当年有人修好栏杆，后来是不是就不会出事？","ln":365},{"t":"d","w":"林澈","x":"可能。但我们无法知道每一个「如果」会怎样。可以确定的是，坏掉的栏杆应该及时修好；知道了问题，也应该把它写在记录里。","ln":366},{"t":"d","w":"女孩","x":"那道歉有什么用？","ln":367},{"t":"d","w":"美咲","x":"道歉不能让那天消失。它是承担责任的开始。之后要让下一次检查真正发生。","ln":368},{"t":"n","x":"女孩想了一会儿，点点头，继续追上同伴。没有闪回，没有音乐突变。我说完那段话，手仍稳稳扶着桌沿。成长有时没有戏剧性的证明，只是某个从前无法说出口的问题，终于可以当作一个问题回答。\n\n导览结束后，我们在空白留言页各写一句。阳葵写「可以慢一点」，玲奈写「请先确认栏杆」，乃爱写「星图每年会调整」。美咲的笔悬了很久，最后写：「离开时，请告诉同行的人。」轮到我，纸上已经没有多少位置。我在最下方添了：「要是没有同行的人，也请告诉自己要去哪里。」","ln":371},{"t":"n","x":"傍晚，五个人沿着坡道往下走。海陵站、学生会室、河堤与纪念馆从不同方向亮起灯。它们像旧游戏里的四个目的地，却不再要求我今晚做出一生的选择。可是冬季申请、考试和面试有各自的时限，迟早会有人转向其中一条路。","ln":376},{"t":"c","o":[{"x":"去海陵站，等美咲从东京面试回来","seg":"A","i":0},{"x":"去学生会旧室，把玲奈忘下的申请夹送去","seg":"B","i":0},{"x":"去河堤，陪阳葵看选拔前最后一次训练","seg":"C","i":0},{"x":"去纪念馆，和乃爱整理遥寄来的新录音","seg":"D","i":0},{"x":"谁也不去，先完成自己的申请清单","seg":"E","i":0}],"ln":380},{"t":"n","x":"我把自己的想法说了出来。","ln":98},{"t":"g","i":42},{"t":"n","x":"我把自己的想法说了出来。","ln":98},{"t":"g","i":42},{"t":"n","x":"我把自己的想法说了出来。","ln":98},{"t":"g","i":42},{"t":"n","x":"美咲说起东京文学馆里那些普通人的手稿，声音渐渐亮起来。","ln":211},{"t":"g","i":104},{"t":"n","x":"美咲停了一下：「别用保证替明天作证。」","ln":211},{"t":"g","i":104},{"t":"n","x":"她点头道谢。夜里，一份改了许多遍的草稿才发到我的手机上。","ln":211},{"t":"g","i":104},{"t":"n","x":"我说出祝福，没说出口的舍不得仍留在心里。","ln":339},{"t":"g","i":180},{"t":"n","x":"「高兴，也会舍不得。」说完后，我第一次觉得这两句话可以同时成立。","ln":339},{"t":"g","i":180},{"t":"n","x":"我把话题推到以后，却知道日历不会替我开口。","ln":339},{"t":"g","i":180}],"A":[{"t":"ch","title":"A-1　站台上没有突然出现的人","ln":394},{"t":"bg","id":"misaki_station","ln":398},{"t":"cast","ids":[],"ln":398},{"t":"n","x":"列车晚了四分钟。美咲在东京参加了一整天的推荐面试，手机最后一条消息是「结束了，坐上车再告诉你」。我站在检票口，才发现自己不知不觉走到了去年她等我的那个位置。那时她问我有没有带礼物；今天我带了两个保温杯，热可可在其中一个里，另一杯是没有放糖的茶，给面试后嗓子发干的她。","ln":401},{"t":"d","w":"美咲","x":"你真的来了。","ln":403},{"t":"d","w":"林澈","x":"你叫我来的。","ln":404},{"t":"d","w":"美咲","x":"我说的是「要不要一起吃饭」。没说让你站在风口。","ln":405},{"t":"d","w":"林澈","x":"谁让出站口只有这一个。","ln":406},{"t":"n","x":"她伸手接过茶，指尖冰凉。车站灯光下，我看见她的眼睛有倦意，也有一种压不住的亮。","ln":409},{"t":"d","w":"林澈","x":"面试怎么样？","ln":411},{"t":"d","w":"美咲","x":"我说完了想说的话。有一题没答好，老师问我为什么写普通人的手稿，我讲得太久。","ln":412},{"t":"d","w":"林澈","x":"这听起来像答得太好。","ln":413},{"t":"d","w":"美咲","x":"你又开始安慰我。","ln":414},{"t":"d","w":"林澈","x":"不是安慰。我听你说过那篇文章，知道你写它的时候是什么样。","ln":415},{"t":"n","x":"她把杯子贴在脸颊上，像确认热度。回家的电车上，美咲讲起东京的街道、校园里开到冬天的树、图书馆窗边一排被人翻得卷边的杂志。她讲得兴奋，又每讲一段便看我一眼，仿佛担心我会被这些不属于海陵的细节推远。","ln":418},{"t":"d","w":"林澈","x":"继续啊。后来呢？","ln":420},{"t":"d","w":"美咲","x":"后来……我站在学院楼前，忽然想，要是以后每天都从那里走出去，也不错。","ln":421},{"t":"d","w":"林澈","x":"嗯。","ln":422},{"t":"d","w":"美咲","x":"你没有别的话？","ln":423},{"t":"d","w":"林澈","x":"有。我想听你在那儿写出什么。","ln":424},{"t":"n","x":"她低下头，把车票整整齐齐地折进笔记本。车窗外没有一场立刻使人和解的雨。只是两座城市间一段真实的铁轨，从今天开始有了可计算的车程。","ln":427},{"t":"ch","title":"A-2　被划掉的申请","ln":429},{"t":"bg","id":"library","ln":433},{"t":"n","x":"面试结果还没来，美咲已经开始准备校内期末考。她把东京大学的资料收在最下层抽屉，桌面摊着海陵本地两所学校的招生页。我从她借给我的笔记本里掉出一张草稿：不是文学稿，而是一封尚未寄出的退出推荐面试后续评估的邮件。正文只有三句，末尾写着「因为个人规划调整」。","ln":436},{"t":"d","w":"林澈","x":"这是什么？","ln":438},{"t":"d","w":"美咲","x":"你看到了？","ln":439},{"t":"d","w":"林澈","x":"从本子里掉出来的。你想退出？","ln":440},{"t":"d","w":"美咲","x":"还没决定。我只是先写个草稿。","ln":441},{"t":"d","w":"林澈","x":"为什么？","ln":442},{"t":"d","w":"美咲","x":"离开海陵要很多钱，住宿、来回车票，还有……很多事。","ln":443},{"t":"n","x":"她把最后三个字说得很轻。我们在一起这一年，没有因为「不能分开」而争吵。恰恰因为我们都知道可以谈，才让这场谈话显得难。她怕自己一说想去东京，我就会为了留住她改申请；我怕自己一说舍不得，她便会把自己缩回熟悉的街道。","ln":446},{"t":"d","w":"林澈","x":"钱可以和家里一起算。还有呢？","ln":448},{"t":"d","w":"美咲","x":"你也在选学校。你爸给你的机会离这里更远。你要是真去了，我们可能隔的不止一条海湾。","ln":449},{"t":"d","w":"林澈","x":"所以你想先放弃？","ln":450},{"t":"d","w":"美咲","x":"我没说我会放弃。我只是……想过。","ln":451},{"t":"d","w":"林澈","x":"你可以想。但别把我猜成一条你必须绕开的路。","ln":452},{"t":"n","x":"她的眼睛忽然红了。","ln":455},{"t":"d","w":"美咲","x":"你也别把「支持我」说得像一句没有成本的好话。你会难过吧？","ln":457},{"t":"d","w":"林澈","x":"会。","ln":458},{"t":"d","w":"美咲","x":"我也会。我只是想听你亲口说。","ln":459},{"t":"n","x":"我终于承认，去年那个答应与她一起拿行李的人，不一定能在每个站台都笑着挥手。我会嫉妒新校园占去她的时间，会在冬天的夜里盯着车次表算下一次见面。但这些不等于要求她留下。美咲听完，反而把那封退出邮件揉成一团又展开，说不能因为害怕就假装自己不想去。","ln":462},{"t":"c","o":[{"x":"「我希望你去东京；我会想你，也想和你一起安排见面的办法。」","i":122},{"x":"「你想去哪就去哪，我没有任何意见。」","i":124},{"x":"「既然这么难，不如都留在海陵。」","i":126}],"ln":464},{"t":"bg","id":"misaki_kitchen","ln":470},{"t":"cast","ids":[],"ln":470},{"t":"n","x":"我们把两所学校的费用、住宿、奖学金和车程写在纸上。她母亲端来切好的橘子，没有问「林澈同不同意」，而是问美咲是否愿意让她帮忙联系一位在东京工作的阿姨。美咲说愿意，并明确提出先独自看宿舍，再考虑借住。她把自己的界限说得很清楚，声音不大，桌上的人都听见了。","ln":473},{"t":"d","w":"美咲母亲","x":"小时候你怕去隔壁家借酱油，站在门口练了半小时。","ln":475},{"t":"d","w":"美咲","x":"妈妈。","ln":476},{"t":"d","w":"林澈","x":"原来这是家族公开资料。","ln":477},{"t":"d","w":"美咲","x":"你别笑。有人小时候睡觉喊炸鸡。","ln":478},{"t":"n","x":"她故意报复，我却在纸上看到她自己写下的第一行：「我想去东京读书。」没有「如果林澈可以」，没有「如果大家不介意」。后面是现实条件，一项一项可以讨论、可以修改。愿望终于不是一句会让别人受伤的秘密。","ln":481},{"t":"ch","title":"A-3　两张不同方向的车票","ln":483},{"t":"bg","id":"sea","ln":487},{"t":"n","x":"美咲收到正式录取通知。她最先打给母亲，第二个打给我。电话里，她先哭了一小会儿，才说出「录取了」三个字。我祝贺她，挂断后一个人站在港口看船。快乐是真的，难过也是真的；两件事在胸口并排站着，谁都没有把谁挤走。\n\n我的预科项目也给了面试邀请。海陵大学人文信息学系的笔试则在同一周。父亲说可以帮我把两个方向的时间排开，美咲递来一张她画的表，上面把我们各自的安排分开，见面计划放在最后一栏。她说：「以前我会先看你去哪儿。现在先看我去哪儿，再听你去哪儿。」","ln":490},{"t":"d","w":"林澈","x":"那我呢？我应该怎么选？","ln":494},{"t":"d","w":"美咲","x":"你不是来让我替你填表的吧？","ln":495},{"t":"d","w":"林澈","x":"我想听你说，你最不愿意看到哪一种结果。","ln":496},{"t":"d","w":"美咲","x":"最不愿意你以后说，「我那时为了你放弃了」。无论你去哪里，都别把账记在我头上。","ln":497},{"t":"d","w":"林澈","x":"我最不愿意你因为怕我不高兴，连东京的书都不敢买。","ln":498},{"t":"n","x":"她从包里拿出一本东京旧书店寄来的诗集，像被当场抓住一样笑了。海风掀起书页，里面夹着一张便利贴：「到新城市后，第一个周末给自己走一条陌生的街。」她说这不是约会计划，只是给独自抵达的自己留的一件小事。我在旁边写下另一张：「无论申请结果如何，春天继续做海陵口述史。」它不要求两张便利贴贴在同一面墙上。","ln":501},{"t":"bg","id":"street_dusk","ln":503},{"t":"n","x":"有同学听说我们可能分隔两地，随口说「异地恋都很难吧」。美咲笑着回答「所以要认真试」，我也没急着拿别人的分手故事反驳。放学后她却问我，是不是觉得她在逞强。","ln":506},{"t":"d","w":"林澈","x":"我觉得你刚才说的是你想说的话。","ln":508},{"t":"d","w":"美咲","x":"是。我还想说，有时候我会后悔让自己这么勇敢。","ln":509},{"t":"d","w":"林澈","x":"后悔哪一部分？","ln":510},{"t":"d","w":"美咲","x":"不是东京。是怕以后忙起来，我会变成那种只在周末发「最近还好吗」的人。","ln":511},{"t":"d","w":"林澈","x":"那就提前约定。如果忙，发「我忙」。如果难过，发「我难过」。不用把每次通话都演成一切顺利。","ln":512},{"t":"d","w":"美咲","x":"如果想见你呢？","ln":513},{"t":"d","w":"林澈","x":"就说想见我。我们一起看车票，买不起的时候也可以一起承认买不起。","ln":514},{"t":"n","x":"她伸手握住我的手，掌心有一点汗。我们把相见当成可计划的事情，也把不能相见当成可说明的事实。这样的约定不浪漫，却使离别有了可以站稳的地面。","ln":517},{"t":"ch","title":"A-4　告别练习","ln":519},{"t":"bg","id":"misaki_park","ln":523},{"t":"cast","ids":[],"ln":523},{"t":"n","x":"长椅的漆比去年旧了一点，美咲依旧买了两罐热可可。她把一罐递给我，说今夜不许用玩笑跳过任何问题。我们便把想到的都问出来：生日要不要一起过，学期中谁先坐车，遇见新朋友会不会吃醋，吵架时可不可以先睡觉再谈。","ln":526},{"t":"d","w":"林澈","x":"我可能申请到海外项目的下一轮。现在还没有最终结果。","ln":528},{"t":"d","w":"美咲","x":"你终于主动说了。","ln":529},{"t":"d","w":"林澈","x":"我想等确定了再告诉你。后来发现，不确定也是你应该知道的事实。","ln":530},{"t":"d","w":"美咲","x":"谢谢。我要是害怕，会问你，不会躲去替你安排更近的学校。","ln":531},{"t":"n","x":"她说话时把可可罐握得太紧，指节发白。我把自己的手覆上去，却没有说「不会分开」。我们确实会在某些日子分开，甚至有一天也许改变心意。承诺能给出的，不是永远不变的结果，而是结果变化时不让对方从陌生人口中得知。","ln":534},{"t":"d","w":"美咲","x":"我写好了那篇散文的结尾。","ln":536},{"t":"d","w":"林澈","x":"愿意读给我听？","ln":537},{"t":"d","w":"美咲","x":"船上的人害怕。但她仍把岸上的灯记在地图上，不是为了随时返航，而是为了知道那片岸曾真真实实照亮她。","ln":538},{"t":"d","w":"林澈","x":"读完了吗？","ln":539},{"t":"d","w":"美咲","x":"还有一句。她到了另一座岛，点亮自己的灯。","ln":540},{"t":"n","x":"我想起她去年说过，真正无法接受的不是我离开，而是我没让她参与决定。现在轮到她准备离开，我们一个问题一个问题地谈，才发现说完整一次告别，花的时间比逃走多，留下的误解却少得多。","ln":543},{"t":"c","o":[{"x":"「我希望你去。我的选择也会由我自己负责；我们认真试着走下去。」","i":85},{"x":"「你留下吧，我会补偿你放弃的机会。」","i":120},{"x":"「既然谁也无法保证未来，现在就别给关系一个名字。」","i":118}],"ln":545},{"t":"n","x":"毕业典礼后的第三天，美咲带着两个行李箱去东京。站台上，她故意把较轻的箱子递给我，问我是否还会说「不用，我自己来」。我握住拉杆，说「一起拿到车门口；剩下的一段你自己拿」。她笑得很厉害，眼睛却湿了。","ln":553},{"t":"d","w":"美咲","x":"你不会害怕吗？","ln":555},{"t":"d","w":"林澈","x":"会。但害怕和阻止你，是两回事。","ln":556},{"t":"d","w":"美咲","x":"我也怕。尤其怕我们以后只记得今天说过的话，不敢说后来的话。","ln":557},{"t":"d","w":"林澈","x":"那后来的话也说。包括不好听的。","ln":558},{"t":"d","w":"美咲","x":"好。第一个周末，我要去走一条陌生的街。晚上给你看照片。","ln":559},{"t":"d","w":"林澈","x":"我那天去海陵档案馆。给你看最丑的旧地图。","ln":560},{"t":"d","w":"美咲","x":"你总能把浪漫说成考古。","ln":561},{"t":"n","x":"广播报站，车门将关。她没有回头来要求我保证永远在原地。我也没有让她别走。她伸出手，在半空做一个很小的挥别，像在纸上写下句号。列车开出去时，我的手机响起，她发来刚拍的照片：站台另一侧的我，背后是海陵明亮的晨光。配字只有一句：「这一次，我知道你在哪里。」我回复：「我也知道你要去哪里。」一个学期后，我们在东京争吵过、和好过，也各自结识了新朋友。感情没有因为距离自动获胜，是我们一次次把困难说出来，才使它有了继续的形状。","ln":564},{"t":"bg","id":"misaki_tokyo_date","ln":566},{"t":"cast","ids":[],"ln":566},{"t":"n","x":"两年后的秋天，我在东京听完美咲的第一次公开朗读。散场后，她换上酒红色短裙和浅色露肩毛衣，笑我在台下比作者本人还紧张。雨刚停，我们沿着有灯的街道走，她主动牵住我的手。","ln":566},{"t":"d","w":"美咲","x":"今晚别急着赶末班车。明早陪我去那家旧书店，好吗？","ln":566},{"t":"d","w":"林澈","x":"好。明天的事，明天一起决定。","ln":566},{"t":"n","x":"她踮起脚吻了我一下，又把手指扣得更紧。楼道的灯亮起时，我们仍在讨论书店几点开门。那些曾经说不出口的愿望，如今可以说得很轻。","ln":566},{"t":"bg","id":"misaki_bookshop","ln":566},{"t":"cast","ids":[],"ln":566},{"t":"n","x":"第二天的旧书店藏在一条很窄的巷子里。美咲翻出一本绝版诗集，我替她从最高一层取下。她把书塞进我手里，说这是给迟到两年的共同书架的第一本。","ln":566},{"t":"d","w":"美咲","x":"你选一本，我选一本。下次见面再交换读后感。","ln":566},{"t":"bg","id":"misaki_festival","ln":566},{"t":"cast","ids":[],"ln":566},{"t":"n","x":"夏天再见时，夜祭的灯笼从街口一直亮到河边。她走在前面，忽然放慢脚步等我；烟花响起，我们才发现手一直牵着。","ln":566},{"t":"d","w":"美咲","x":"这次我没有在心里排练要说什么。只是想和你一起看完。","ln":566},{"t":"bg","id":"misaki_seaside_cafe","ln":566},{"t":"cast","ids":[],"ln":566},{"t":"n","x":"返乡的周末，我们在海边咖啡馆碰面。美咲把第二杯冰茶推给我，像当年递来那把伞一样自然。她说新稿写的是两个不断出发、也不断回家的人。","ln":566},{"t":"d","w":"林澈","x":"那他们后来呢？","ln":566},{"t":"d","w":"美咲","x":"还没写到后来。你陪我慢慢想。","ln":566},{"t":"bg","id":"misaki_balcony","ln":566},{"t":"cast","ids":[],"ln":566},{"t":"n","x":"秋末，她把公寓阳台上的两盆花往避风处挪了挪。远处电车经过，灯光像一行尚未落笔的句子。我们对着明年的日历，认真圈出能一起度过的日子。","ln":566},{"t":"d","w":"美咲","x":"不用每一次都完美。能一起商量，就已经很好。","ln":566},{"t":"e","kind":"GOOD","line":"A","title":"把离开说完整","ln":550},{"t":"n","x":"毕业后两人暂时结束恋爱，以朋友身份保持联系。美咲到了东京，不再为发消息犹豫半小时；林澈仍在海陵继续自己的申请。秋天他们约在两城中间的小站见面，没有人问「能不能回到从前」。美咲说：「今天想见你，就约了。下一次要不要见，到时候再说。」这不是否定过去，而是承认过去无法替未来签字。","ln":568},{"t":"e","kind":"NORMAL","line":"A","title":"慢车","ln":568},{"t":"n","x":"美咲最终留在海陵，告诉亲友「这是我的决定」，却再不向林澈讲东京文学馆的事。某晚她把未寄出的散文稿投进回收箱，林澈想替她捡起，她说：「你看，你又觉得自己知道我需要什么。」第二年，她独自重新申请外地学校。她离开前终于说出那句过去最难说的话：「我很难过。」站台没有争吵，只剩两个人承认，陪伴不能以一个人的未来作抵押。","ln":570},{"t":"e","kind":"BAD","line":"A","title":"替你留下","ln":570},{"t":"n","x":"美咲接过我的话，开始认真数哪几个周末能见面。","ln":464},{"t":"g","i":42},{"t":"n","x":"美咲轻声问：「没有意见，也可能是把谈话关掉吧？」","ln":464},{"t":"g","i":42},{"t":"n","x":"美咲没有马上回答。我们都明白，这句话仍需重新谈。","ln":464},{"t":"g","i":42}],"B":[{"t":"ch","title":"B-1　退回的信封","ln":578},{"t":"bg","id":"student_council","ln":582},{"t":"n","x":"玲奈忘在桌上的申请夹仍按颜色分好了页签：蓝色是课程资料，绿色是作品清单，红色是面试问题。她离开前说去教务处交补充材料，很快回来。我等了半小时，窗外路灯亮起，才看见她从走廊那头走来。她手里拿着一个退回的信封，边角被捏出几道痕。","ln":585},{"t":"d","w":"林澈","x":"怎么了？","ln":587},{"t":"d","w":"玲奈","x":"文学部提前招生，第一轮没通过。作品评分和面试评分都不够。","ln":588},{"t":"d","w":"林澈","x":"你要坐下吗？","ln":589},{"t":"d","w":"玲奈","x":"先把夹子给我。还有两场考试，今天晚上要调整复习表。","ln":590},{"t":"n","x":"她伸手接文件，手却有一点发抖。去年在海陵大学开放日，她能把「我想读这个」说得响亮；此刻第一道真正属于她自己的选择撞上墙，疼痛仍然实实在在。她没有重新变成只会听父亲话的学生会长，也没有立刻学会不在乎失败。她只是站在旧室门口，竭力不让眼泪落到被评分的纸上。","ln":593},{"t":"d","w":"林澈","x":"今晚不调整也来得及。","ln":595},{"t":"d","w":"玲奈","x":"我知道来得及。我现在需要做一件能算得出结果的事。","ln":596},{"t":"d","w":"林澈","x":"那先算我们还有多少时间吃晚饭。","ln":597},{"t":"d","w":"玲奈","x":"你这种时候还有心情开玩笑。","ln":598},{"t":"d","w":"林澈","x":"我怕一认真，你就替我写一份安慰工作流程。","ln":599},{"t":"n","x":"她忍不住笑了一下，接着眼泪落下来。我们在学生会旧室吃便利店的热饭团，玲奈一面咬一面看成绩说明。评分里有一句「论述自成体系，但研究问题过宽」。她重复读了三遍，像想从字缝里找出自己不该喜欢这个专业的证据。","ln":602},{"t":"d","w":"玲奈","x":"我父亲当年说我不适合做没有标准答案的事。","ln":604},{"t":"d","w":"林澈","x":"他对你熟悉，不代表每次判断都正确。","ln":605},{"t":"d","w":"玲奈","x":"我也不因为反对他就自动正确。今天的分数是真的。","ln":606},{"t":"d","w":"林澈","x":"对。分数是真的。你想研究那些手稿，也是真的。","ln":607},{"t":"n","x":"她将成绩单放平。这不是一句能使她快乐起来的话，却允许两件事实同时留在桌上。夜色深时，她终于打电话给母亲，只说「没过」，没有先替自己解释。母亲说今晚可以回家吃草莓蛋糕，也可以在外面散步，随她选。玲奈看我一眼，说想先散步。","ln":610},{"t":"ch","title":"B-2　旧道路重新开放","ln":612},{"t":"bg","id":"room","ln":616},{"t":"n","x":"玲奈父亲得知结果，没有责备。他拿出一份东京大学的合作推荐项目：当年预审的资格还在，若她愿意，可转到一个课程结构明确、毕业去向清楚的行政管理方向。截止日期在两周后。他将文件放在餐桌中央，叮嘱她先读，再决定。","ln":619},{"t":"d","w":"玲奈父亲","x":"我不会像去年那样把车停在学校门口。你有权拒绝。但我希望你别因为曾经拒绝过，就觉得这条路现在也不能看。","ln":621},{"t":"d","w":"玲奈","x":"我会看。谢谢。","ln":622},{"t":"n","x":"我站在玄关，没有参与那场父女谈话。出来以后，玲奈把资料放进包里，长长呼出一口气。她说父亲改变了说话方式，反倒使她更难把东京项目一概当作不属于自己的答案。她不想成为「永远与父亲相反」的黑川玲奈。她想知道，每一门课到底教什么，每一座城市到底给她什么生活。","ln":625},{"t":"d","w":"林澈","x":"你可以同时看。","ln":627},{"t":"d","w":"玲奈","x":"我知道。让我难受的是，我第一次必须承认，有些路我也许走不通。","ln":628},{"t":"d","w":"林澈","x":"你以前就知道别人的计划可能失败。","ln":629},{"t":"d","w":"玲奈","x":"轮到自己，理论突然变得很难用。","ln":630},{"t":"n","x":"她列出三份方案：海陵大学普通入学考试，东京合作推荐，来年重新申请研究方向。第一页的标题原本写「最优解」，她看了很久，划掉，改成「可承担的选择」。那晚我们一起查课程，不用「好学校」三个字替代具体课程，也不把「留在海陵」当作爱情的奖品。","ln":633},{"t":"c","o":[{"x":"陪她核对两所学校的课程、费用与截止日期，不替她排优先级。","i":122},{"x":"建议她接受东京推荐，免得再失败一次。","i":124},{"x":"建议她只考海陵大学，以证明去年反对父亲是正确的。","i":126}],"ln":635},{"t":"bg","id":"reina_library","ln":641},{"t":"cast","ids":[],"ln":641},{"t":"n","x":"玲奈去听一位老师讲口述史中的沉默：受访者停顿的地方，研究者应不应该替他写出未说的话。她记满三页，结束后留下问问题。老师看了她的申请书，指出研究范围太大，如果选一个具体街区、一段时间，也许更有力量。玲奈没有像收到评分那夜一样僵住，甚至当场问：「如果我缩小问题，会不会失去我最在意的东西？」\n\n老师说，缩小范围不等于缩小关心。把一条街讲清楚，比把整座城概括成几个好看的词更尊重生活在其中的人。回程电车上，玲奈把新题目写在玻璃的雾气里：「港口搬迁后，旧街区的店主怎样讲述离开」。字刚写完，就被她用掌心擦掉。","ln":644},{"t":"d","w":"玲奈","x":"我不是要装作这场失败是好事。","ln":648},{"t":"d","w":"林澈","x":"它本来就不是。","ln":649},{"t":"d","w":"玲奈","x":"但这位老师说的，我想试。","ln":650},{"t":"d","w":"林澈","x":"那就试。失败不负责证明所有问题都错了。","ln":651},{"t":"n","x":"她靠着窗，轻轻「嗯」了一声。我们没有拥抱，也没有把退信拍成励志照片。一个新的题目需要重新读资料、访问愿意受访的人、认真准备考试；这些工作不会因为一句漂亮的话自动完成。","ln":654},{"t":"ch","title":"B-3　一次不体面的争吵","ln":656},{"t":"bg","id":"reina_riverside","ln":660},{"t":"cast","ids":[],"ln":660},{"t":"n","x":"玲奈的普通入学模拟考成绩有起伏。我的海外项目面试邀请也到了。两个人都忙，通话从每晚变成隔两晚，见面时话题常常只剩「进度怎样」。那晚她问我会不会申请海外项目，我说会，先去面试，不代表最终离开。她沉默了一阵。","ln":663},{"t":"d","w":"玲奈","x":"你总说不替别人选，轮到自己却把每条路都留着。","ln":665},{"t":"d","w":"林澈","x":"截止时间还没到，我为什么不能准备？","ln":666},{"t":"d","w":"玲奈","x":"我不是说不能。我只是……讨厌你听起来永远像有退路。","ln":667},{"t":"d","w":"林澈","x":"我也会失败。你明明知道。","ln":668},{"t":"d","w":"玲奈","x":"知道。可我现在嫉妒你可以平静地谈失败。我每天醒来都想起那张评分单。","ln":669},{"t":"n","x":"她第一次把「嫉妒」这样不体面的词放到我们之间。我也没那么成熟。我说「当初是你自己选的」，听起来像把她所有痛都推回她怀里。她立刻停住脚步。","ln":672},{"t":"d","w":"玲奈","x":"这句我已经每天对自己说了，不需要你再说一遍。","ln":674},{"t":"d","w":"林澈","x":"我说错了。","ln":675},{"t":"d","w":"玲奈","x":"嗯。你说错了。","ln":676},{"t":"n","x":"她没有接我的道歉，也没有转身逃走。我们走完那条步道，各自回家。第二天，我给她发消息，写清自己究竟想表达什么：「选择属于你，所以失败不能拿来证明你不该拥有选择。我昨天把前半句说得像审判，抱歉。」她回：「我也不该因为害怕，就把你准备海外项目说成轻松。今晚见面，先吃饭。」","ln":679},{"t":"bg","id":"reina_diner","ln":681},{"t":"cast","ids":[],"ln":681},{"t":"n","x":"我们点了两碗热汤面。玲奈说她看完东京合作项目的课表，发现其中一门公共政策课很感兴趣，但整体方向不是她愿意读四年的东西。她打算参加海陵的普通入学考试，同时保留东京项目到最后期限再决定。她不需要我称赞勇敢，只需要我听见这个具体安排。","ln":684},{"t":"d","w":"林澈","x":"如果结果还是不理想呢？","ln":686},{"t":"d","w":"玲奈","x":"先允许我今晚不知道。到那天我会再做一个决定。","ln":687},{"t":"d","w":"林澈","x":"我会在。","ln":688},{"t":"d","w":"玲奈","x":"你可以在，但不许替我替老师写评分意见。","ln":689},{"t":"d","w":"林澈","x":"这个权限本来也不在我手里。","ln":690},{"t":"n","x":"她笑起来，汤面的热气模糊了镜片。曾经我们用「长期共犯」开玩笑，如今才知道，共犯关系不意味着互相保证胜利，而是有人承认自己失手时，另一人仍愿意坐在同一张桌边。","ln":693},{"t":"ch","title":"B-4　母亲的草莓蛋糕","ln":695},{"t":"bg","id":"room","ln":699},{"t":"n","x":"玲奈母亲已经能自己出门买菜，仍偶尔会疲倦。她做了一块不大整齐的草莓蛋糕，奶油抹得薄厚不均。玲奈下意识拿起刀，想把边缘修平。母亲按住她的手，说「今天的蛋糕就是这样，别给它补考」。父亲在一旁笑了一声，又很快装作咳嗽。","ln":702},{"t":"d","w":"玲奈父亲","x":"东京项目的回复期限是明晚。你想好了吗？","ln":704},{"t":"d","w":"玲奈","x":"想好了。我不参加。","ln":705},{"t":"d","w":"玲奈父亲","x":"因为林澈？","ln":706},{"t":"d","w":"玲奈","x":"因为课程。我喜欢其中一门，但不愿意为了那一门读一套与我想做的工作距离很远的训练。还有，我希望继续在海陵采访旧街区的人。","ln":707},{"t":"d","w":"玲奈父亲","x":"这次你说得很具体。","ln":708},{"t":"d","w":"玲奈","x":"因为我认真看过了。去年我只知道自己不想被安排；今年我知道自己想怎样学习。","ln":709},{"t":"n","x":"父亲点头，没有说「你一定会成功」，也没有说「到时候别后悔」。他只是把申请截止的提醒从家庭日历上删去。玲奈看着那个动作，眼眶忽然红了。原来理解有时是一个人撤回替你设置的闹钟。\n\n晚上我们沿着旧街区散步。她指着一间正在搬迁的修鞋店，说打算征求店主同意后做第一份访谈。这里的小巷既是她的研究对象，也是她长大的地方；读海陵大学也许会让她继续留在城里，但她说自己不会再拿「留下」当成对爱情的证明。","ln":712},{"t":"d","w":"玲奈","x":"如果你以后去海外，我们要另谈。不能用我这次的选择要求你留。","ln":716},{"t":"d","w":"林澈","x":"我知道。我同样不要求你跟我去。","ln":717},{"t":"d","w":"玲奈","x":"很好。先把考试考完，才有资格讨论机票。","ln":718},{"t":"d","w":"林澈","x":"会长的命令？","ln":719},{"t":"d","w":"玲奈","x":"女朋友的建议。语气可以自行调整。","ln":720},{"t":"n","x":"风把她的围巾掀起，我伸手替她压住。她却先替我把没拉好的外套拉链拉到领口。两个总以为自己负责照顾对方的人，在小巷里互相挡了一阵风，没有谁因此欠谁一个未来。","ln":723},{"t":"ch","title":"B-5　没有标准答案的考场","ln":725},{"t":"bg","id":"street_dusk","ln":729},{"t":"n","x":"考试那天，玲奈没有带当年那个装满备用文具的巨大笔袋。她只带一支笔、一支备用笔和一块草莓糖。我们在校门口碰面，她把糖掰成两半，递给我小的一半。我问这是效率管理，还是故意偏心；她说我的嗓子刚好，不需要太甜。","ln":732},{"t":"d","w":"玲奈","x":"我可能考不上。","ln":734},{"t":"d","w":"林澈","x":"嗯。","ln":735},{"t":"d","w":"玲奈","x":"你能不能说点更体贴的话？","ln":736},{"t":"d","w":"林澈","x":"可以。你准备过，也问过自己为什么要来。今天只需把会的写出来。考不上，我们再看下一张地图。","ln":737},{"t":"d","w":"玲奈","x":"这句可以。","ln":738},{"t":"n","x":"她走向校门口，又折回来，轻轻抱了我一下。没有镜头里的慢动作，背后有考生催着排队。她放开我，说「等我考完再吃蛋糕」。我看她走进人群，忽然明白去年在校门口停着的那辆去东京的车之所以令人窒息，并不是东京本身，而是车门关上前她没有被允许问自己要去哪里。","ln":741},{"t":"c","o":[{"x":"等她考完，只问她想不想谈结果，再讨论自己的申请。","i":88},{"x":"提前给她规划复读、转专业和东京备用方案，以免她失望。","i":120},{"x":"若她失利，先隐瞒自己的海外项目录取消息。","i":118}],"ln":743},{"t":"n","x":"成绩公布那天，玲奈没有拿到第一志愿的最高分，却在普通入学考试中达到了海陵大学文学部的录取线。她盯着屏幕看了许久，先打电话给父母，再给我发来一张截图，附一句「这个分数不完美」。我回：「这个分数属于你。」她马上打来电话，说我越来越会用她的话堵她的嘴。\n\n一个月后，我收到海外项目的正式录取，也拿到海陵大学人文信息学系的录取。玲奈陪我列费用与课程，并认真指出海外项目的奖学金有条件，海陵的档案馆实习则很适合我。我最后选了留在海陵读本科，同时参加暑期海外档案工作坊。我把理由一条条说给她听，其中包括研究方向、费用、对海陵资料的兴趣，也包括我想与她在同一座城生活；最后一条不是她必须承担的债，只是我愿意承认的心意。","ln":751},{"t":"d","w":"玲奈","x":"你确定？","ln":755},{"t":"d","w":"林澈","x":"这次我已经把申请书、预算和后悔的可能都看过了。确定。","ln":756},{"t":"d","w":"玲奈","x":"如果有一天你改变主意，记得告诉我。","ln":757},{"t":"d","w":"林澈","x":"会。你也是。","ln":758},{"t":"n","x":"开学后，她的第一次田野访谈被店主婉拒。玲奈带着记录本回到咖啡馆，说「好像又失败一次」。我问要不要换一家，她摇头，打算先写一封说明采访目的的信，给店主选择的时间。她没有因为考进想去的学校就从此拥有正确答案；她只是终于相信，错误的可能不会剥夺她继续选择的权利。傍晚我们路过那家修鞋店，灯还亮着。她伸手牵住我，步子没有比从前慢，却不再像在追赶谁的评分表。","ln":761},{"t":"bg","id":"reina_campus_date","ln":763},{"t":"cast","ids":[],"ln":763},{"t":"n","x":"大学二年级的一个傍晚，我在咖啡馆等玲奈交完访谈稿。她穿着黑色短裙，外套随意搭在肩上，把一杯还温着的咖啡推到我面前。","ln":763},{"t":"d","w":"玲奈","x":"今晚的计划表只有一项：和你散步。你有异议吗？","ln":763},{"t":"d","w":"林澈","x":"能加一项牵手吗？","ln":763},{"t":"n","x":"她先装作审阅提案，随后把手放进我掌心。窗外的夕光慢慢暗下去，我们谁也没有急着为这一天写出正确答案。","ln":763},{"t":"bg","id":"reina_archive","ln":763},{"t":"cast","ids":[],"ln":763},{"t":"n","x":"玲奈的访谈项目终于收尾。档案室里只剩我们，她把最后一份资料递来，难得没有催我核对编号。","ln":763},{"t":"d","w":"玲奈","x":"今天的归档可以延后十分钟。我想先听你说说近况。","ln":763},{"t":"bg","id":"reina_waterfront","ln":763},{"t":"cast","ids":[],"ln":763},{"t":"n","x":"秋夜的港口风大，我们沿着护栏慢慢走。她说起下一学期的调查计划，也听完我对未来仍不确定的部分。","ln":763},{"t":"d","w":"玲奈","x":"计划可以改。你说的话，我会记得。","ln":763},{"t":"bg","id":"reina_kitchen","ln":763},{"t":"cast","ids":[],"ln":763},{"t":"n","x":"周末第一次一起做晚饭，玲奈负责看菜谱，我负责把盐和糖放回正确位置。锅里的热气升起，她终于承认两人一起摸索比照着步骤做有趣。","ln":763},{"t":"d","w":"林澈","x":"那下周还做吗？","ln":763},{"t":"d","w":"玲奈","x":"可以。记得带你上次说的那本书。","ln":763},{"t":"bg","id":"reina_gallery","ln":763},{"t":"cast","ids":[],"ln":763},{"t":"n","x":"她的小型展览开幕那天，照片旁写着受访者亲自确认过的话。玲奈站在入口，等最后一位来宾离开后才朝我伸手。","ln":763},{"t":"d","w":"玲奈","x":"这一次，我想把完成的东西先给你看。","ln":763},{"t":"e","kind":"GOOD","line":"B","title":"错误答案的权利","ln":748},{"t":"n","x":"玲奈没考上海陵大学第一志愿，选择一年后重新申请，同时在社区档案馆做助理。我去海外项目读预科。我们仍然交往，却花了很久才适应彼此不能替对方消化失败。某次视频通话，她说今天访谈又被拒绝，我说项目报告也被老师退回；两人沉默片刻，一起笑了。关系没有因结果整齐而稳定，而是因为两个人都愿意把不整齐的生活拿出来谈。","ln":765},{"t":"e","kind":"NORMAL","line":"B","title":"重新选题","ln":765},{"t":"n","x":" 且拒绝承认越界。玲奈照我列的备用方案走，成绩虽好，却渐渐不再说自己喜欢哪些课。某天她把我的计划表原样退还，纸上只有一句：「这次我不再需要另一个人替我证明自己做得对。」我们礼貌地分开。后来我听说她转向地方新闻研究，第一次独立发表文章的题目正是《被回答之前》。我没有去祝贺，终于明白被信任并不等于被授予对她人生的管理权。","ln":767},{"t":"e","kind":"BAD","line":"B","title":"正确的沉默","ln":767},{"t":"n","x":"玲奈把两份课程表推到中间，我们一条一条地核对。","ln":635},{"t":"g","i":31},{"t":"n","x":"玲奈合上文件夹：「谢谢，但先让我自己想完。」","ln":635},{"t":"g","i":31},{"t":"n","x":"玲奈望着我：「考试不是为了证明去年谁对谁错。」","ln":635},{"t":"g","i":31}],"C":[{"t":"ch","title":"C-1　没有跑表的晚上","ln":775},{"t":"bg","id":"himari_riverside","ln":779},{"t":"cast","ids":[],"ln":779},{"t":"n","x":"阳葵的教练在跑道边数着最后一组，声音穿过冷风，像一串抛向远处的石子。她冲线后没有立刻趴下，先慢走、伸展，再看自己的膝盖有没有异常。去年她取下号码布时，以为一切与跑道有关的日子都结束了；如今她又站在这里，懂得在下一次起跑前把身体带回家。","ln":782},{"t":"d","w":"阳葵","x":"你带水了吗？","ln":784},{"t":"d","w":"林澈","x":"带了。还有毛巾。","ln":785},{"t":"d","w":"阳葵","x":"男朋友呢？","ln":786},{"t":"d","w":"林澈","x":"这个东西已经自动续费一年。","ln":787},{"t":"d","w":"阳葵","x":"那服务评价给四星。","ln":788},{"t":"d","w":"林澈","x":"少的一星呢？","ln":789},{"t":"d","w":"阳葵","x":"不会在我冲线前大喊「我在终点等你」。","ln":790},{"t":"n","x":"她用玩笑说完，眼睛却看着教练夹板上的数据。今天的速度不错，仍比大学队的选拔标准慢一点。北陆体育大学愿意给她一次试训，不保证录取，更不保证将来能成为职业选手。她最怕的并非失败，而是重新把那个冷冰冰的数字当成自己的全部。","ln":793},{"t":"d","w":"林澈","x":"不喊是怕你觉得我替你安排了终点。你要我喊，我就喊。","ln":795},{"t":"d","w":"阳葵","x":"今天不用。陪我走回家就好。","ln":796},{"t":"n","x":"我们沿河慢慢走。她讲起志愿服务中心那个总说脚疼的小学生，后来在复健师指导下能跑完操场半圈，跑完时没有名次，却追着她问下一次什么时候见。她说自己竟比看比赛录像还高兴。风把她的头发吹得乱七八糟，我想伸手替她整理，她偏头躲开，说等回家再梳，河边吹一吹很舒服。","ln":799},{"t":"ch","title":"C-2　邀请函背面的条件","ln":801},{"t":"bg","id":"room","ln":805},{"t":"n","x":"北陆体育大学的选拔通知写得详细：体能测试、训练观察、医学评估，以及运动康复课程体验。阳葵父母没有立刻庆祝。她的父亲问长期训练会不会增加旧伤风险；母亲问如果队里很忙，是否还有时间认真上课。阳葵第一次没有用「我没事」把他们打发走，而是把医生的复诊意见放在桌上，解释哪些强度可以接受，哪些情形必须暂停。","ln":808},{"t":"d","w":"阳葵父亲","x":"如果教练让你超过这个范围呢？","ln":810},{"t":"d","w":"阳葵","x":"我会先和他讨论。真不行，我就退出那次训练。","ln":811},{"t":"d","w":"阳葵母亲","x":"这话是你说的，我记住了。","ln":812},{"t":"d","w":"阳葵","x":"你们可以提醒，但别替我把鞋收起来。","ln":813},{"t":"n","x":"她母亲点点头，转而问我对她去外地怎么看。阳葵抢先说：「这题由他自己答，和我的决定不是同一张卷子。」她明明紧张，仍坐得笔直。我回答，我会想她，愿意一起试试远距离的生活，也知道自己不懂专业训练，需要她和医生、教练一起判断。阳葵低头笑了，像终于听到一句不把她当易碎物品的话。\n\n回家路上，她却忽然停在自动售货机前。","ln":816},{"t":"d","w":"阳葵","x":"要是我被录取，你在海陵。我们可能一年只见几次。","ln":820},{"t":"d","w":"林澈","x":"嗯。","ln":821},{"t":"d","w":"阳葵","x":"你真的不拦我？","ln":822},{"t":"d","w":"林澈","x":"我可以说会舍不得。拦你是另一回事。","ln":823},{"t":"d","w":"阳葵","x":"去年你说陪我跑。现在跑道可能通到很远的地方。","ln":824},{"t":"d","w":"林澈","x":"我当时也没规定一定要跑在你旁边。","ln":825},{"t":"n","x":"她沉默许久，买了一瓶橘子汽水，拉环却没立刻打开。阳葵说自己也舍不得，更怕训练忙到无暇做那个会突然跑来找我的人。她在我的生活里一直那么响亮，似乎不需要担心被忘记；可离开以后，她怕变成手机屏幕上每天只能亮几秒的名字。","ln":828},{"t":"d","w":"林澈","x":"你不用用每天出现来证明我喜欢你。","ln":830},{"t":"d","w":"阳葵","x":"也别要求我因为被你喜欢，就不想天天见你。","ln":831},{"t":"d","w":"林澈","x":"好。我们都承认。","ln":832},{"t":"c","o":[{"x":"问她自己想从试训中确认什么，再一起看交通与日程。","i":106},{"x":"保证将来所有比赛都去现场，无论费用和时间。","i":108},{"x":"说职业运动太辛苦，建议她只把跑步当爱好。","i":110}],"ln":834},{"t":"ch","title":"C-3　雪线以北","ln":840},{"t":"bg","id":"himari_track","ln":844},{"t":"cast","ids":[],"ln":844},{"t":"n","x":"我并没有陪阳葵去试训。那是她与大学队、自己的身体和未定的未来之间的一周。出发前她把一张滑稽的海龟贴纸贴在我的志愿表上，叫我趁她不在认真准备自己的面试。我们约好每天晚上发一条消息，有话再打电话；若训练太晚，只发一个句号也算平安。\n\n第一天，她发来食堂的照片，份量大得像要喂一整支球队。第二天，她发来运动康复课的笔记，上面写着「运动员有权报告疼痛」。第三天晚饭后没有消息。我看了几次手机，克制住打给教练的冲动。午夜，她终于发来：「今天测试中途停了。旧伤附近有轻微不适，医生说先检查。别紧张，我也在学别紧张。」\n\n我打电话过去。她的声音很稳，甚至先问我吃过饭没有。检查显示并非新伤，但建议将接下来两天的训练量减半。她答应了。真正使她难受的是：同组一个女生跑得很快，教练当场夸她；阳葵明知自己该停，却还是听见心里有个旧声音说「再坚持一下就能追上」。","ln":847},{"t":"d","w":"阳葵","x":"我把鞋带解开了。站在跑道外看她们跑，突然很想哭。","ln":853},{"t":"d","w":"林澈","x":"你可以哭。","ln":854},{"t":"d","w":"阳葵","x":"我不是怕疼。我怕选拔名单只记得跑完的人。","ln":855},{"t":"d","w":"林澈","x":"你可以告诉教练你的问题，也可以问他们如何看医学评估。名单该由完整表现决定，不是由你隐瞒疼痛换来。","ln":856},{"t":"d","w":"阳葵","x":"知道。说出来还是难。","ln":857},{"t":"d","w":"林澈","x":"我陪你把话练一遍。","ln":858},{"t":"n","x":"我们在电话两端排演她明天要问教练的问题。她第一遍说得像道歉，第二遍说得像挑战，第三遍终于只是陈述事实：「我的膝盖附近有不适，医生建议减量。我想知道队里如何安排有伤史的选手。」她说完自己笑了：「原来一句话不需要跑着讲。」\n\n第四天，她听到教练的答复。队里有医疗团队，也有停训标准；他们不会因她报告疼痛就立刻除名，但最终录取仍看综合表现。她把这些写在日志里，没有把它当成录取的承诺。试训结束那天，她去旁听运动康复课程，认识一位曾经是游泳选手的学姐。对方说退役后仍喜欢水，才读了现在的专业。阳葵在笔记里写：「我也想在离开跑道的一天，继续喜欢跑步。」","ln":861},{"t":"ch","title":"C-4　比名次更难的决定","ln":865},{"t":"bg","id":"station_year","ln":869},{"t":"n","x":"她拖着行李出来，第一件事是把整周的日志摊在我面前。从训练速度到膝盖感觉，从食堂菜单到科学馆的展览票，密密麻麻写满十几页。她还没收到结果，已经说想认真申请那所大学的运动康复课程，即便田径队不录取，她也愿意考虑去读。","ln":872},{"t":"d","w":"林澈","x":"所以你喜欢的不只是一条跑道。","ln":874},{"t":"d","w":"阳葵","x":"嗯。以前我以为承认这一点，就是承认自己不够喜欢跑。现在想想，我喜欢跑步，才想知道人为什么会受伤，怎样才能继续跑。","ln":875},{"t":"d","w":"林澈","x":"你把海龟送给我，原来是科研计划。","ln":876},{"t":"d","w":"阳葵","x":"那是防止你拖延的警示标志。","ln":877},{"t":"n","x":"结果在两周后到来。她通过学术课程的提前评估，田径队则给了有条件录取：开学后先按医学建议参加观察期，达到训练要求才进入正式比赛名单。这既不是「一夜之间成为职业选手」，也不是「梦想落空」。真正的决定细碎又现实：是否接受观察期的限制，是否准备文化课考试，是否搬到离海陵很远的地方。\n\n阳葵的父母提醒她，观察期内有机会，也有竞争和疲劳。她把自己签过字的训练计划拿给他们，承诺按医生意见休息，但不承诺永远不受伤。没有人能作出那种承诺。她还问了学校是否允许更换专业方向，得到一份写着条件的正式答复。她把每项看完，才告诉我：「我想去。」","ln":880},{"t":"d","w":"林澈","x":"这一次不是为了证明你跑得快？","ln":884},{"t":"d","w":"阳葵","x":"我当然想跑得快。但更想看看，我能不能成为会照顾自己、也能帮助别人的运动员。","ln":885},{"t":"d","w":"林澈","x":"这个答案很像你。","ln":886},{"t":"d","w":"阳葵","x":"说得好像你很懂我。","ln":887},{"t":"d","w":"林澈","x":"还在继续学。","ln":888},{"t":"bg","id":"himari_aquarium","ln":890},{"t":"cast","ids":[],"ln":890},{"t":"n","x":"阳葵提出重去去年看水母的地方。上次她惊讶于不跑步的下午也可以快乐；这次她穿着队服外套，站在蓝色水箱前说，如果以后忙到没空看海，她就把这张照片放在宿舍。我们在馆内走了很久，遇见一个小孩盯着海龟问为什么它游得比鱼慢。阳葵蹲下说：「因为它用自己的方式游。慢不代表它没去过远方。」\n\n孩子跑去找家长，她站起身，耳尖有一点红。","ln":893},{"t":"d","w":"林澈","x":"这句你偷练了多久？","ln":897},{"t":"d","w":"阳葵","x":"两分钟。别看我。","ln":898},{"t":"n","x":"我在出口买了一个小海龟挂件，挂到她包上。她摸了摸，说以后无论跑进哪座体育场，都能把那个慢家伙带进去。她也给我挑了一只海星。我说海星没有跑道，她说正好负责提醒我别把人生规划全写成比赛。","ln":901},{"t":"ch","title":"C-5　终点并非地址","ln":903},{"t":"bg","id":"playground","ln":907},{"t":"n","x":"操场上最后一批彩纸被风卷到弯道。阳葵换上跑鞋，却没有启动计时器。她说要和我跑一圈「毕业限定慢跑」。我们跑得很慢，慢到可以把三年来每一件荒唐事说出来：她怕青蛙，玲奈藏草莓拿铁，乃爱抓一次就抓到玩偶，我第一次晨跑不到半圈便扶着围栏。","ln":910},{"t":"d","w":"阳葵","x":"那时候我想，怎么会有人跑这么慢。","ln":912},{"t":"d","w":"林澈","x":"现在呢？","ln":913},{"t":"d","w":"阳葵","x":"现在觉得跑得慢的人也能陪我很久。","ln":914},{"t":"n","x":"到终点时，她故意比我晚一步，问我有没有什么重要的话。我想起去年那句「不管跑不跑，我都在终点等你」，却知道今天的终点不是跑道白线，而是她要去的每一个地方、我可能去的每一个地方，以及我们之间需要不断重新商量的距离。","ln":917},{"t":"c","o":[{"x":"「你按自己的节奏跑。我会安排能做到的相见，也会把我的路告诉你。」","i":72},{"x":"「我会放下一切，跟你到每一场比赛。」","i":104},{"x":"「你去吧，等有了成绩再回来找我。」","i":102}],"ln":919},{"t":"n","x":"阳葵去了北陆。开学后，她没有立刻进入正式比赛名单。观察期里有一次旧伤不适，她主动报告，休息一周，随后重新训练。林澈在海陵读城市档案方向，一边学习，一边做周末口述史志愿者。我们的消息有时密集，有时隔两天才补上一句「刚从图书馆出来」。第一次异地争吵，是我错过她的一场重要测试；她说自己不想听「有成绩了再通知我」，我解释自己的课程冲突，也承认忘了提前告诉她。后来我们学会把期待写进日历，不能做到就说清楚。\n\n两年后，阳葵作为大学队正式选手参加跨校接力赛。她并非队里最快的那一个，却在交棒前顶住了逆风。她跑完后没有寻找摄像机，先看腿有没有异常，再抬头找看台。我坐在中间一排，身旁是她父母和那只已经磨旧的小海龟。她穿过人群，额头上全是汗。","ln":927},{"t":"d","w":"阳葵","x":"我今天快吗？","ln":931},{"t":"d","w":"林澈","x":"快。也跑得很聪明。","ln":932},{"t":"d","w":"阳葵","x":"你是不是每次都这么说？","ln":933},{"t":"d","w":"林澈","x":"不。上次你前半程太急，我说过。","ln":934},{"t":"d","w":"阳葵","x":"对，你这个讨厌的诚实观众。","ln":935},{"t":"n","x":"她把接力棒交还队友，又来握我的手。终点没有固定地址，它随她的脚步移动，也随我的生活改变。我们不必每时每刻站在同一条线上；只要愿意互相告知，愿意在能抵达的日子去见对方，远方就不必成为消失的同义词。","ln":938},{"t":"bg","id":"himari_relay_date","ln":940},{"t":"cast","ids":[],"ln":940},{"t":"n","x":"散场后，阳葵换上一件轻外套，运动短裙的衣角被晚风吹起。她从看台下跑来，手伸得比终点线还早。我握住她的手，她却顺势把我拉近。","ln":940},{"t":"d","w":"阳葵","x":"这次不用跑，你陪我慢慢走回去。","ln":940},{"t":"d","w":"林澈","x":"四星服务，今天能升五星吗？","ln":940},{"t":"n","x":"她笑着在我脸颊亲了一下，随即又说别让我得意。跑道的灯一盏盏亮起，我们并肩走出了体育场。","ln":940},{"t":"bg","id":"himari_training","ln":940},{"t":"cast","ids":[],"ln":940},{"t":"n","x":"大学校队训练结束后，阳葵还留在跑道边做拉伸。她朝我挥手，呼吸尚未平稳，笑容却一点没变。","ln":940},{"t":"d","w":"阳葵","x":"今天不比速度。你陪我把最后一圈走完。","ln":940},{"t":"bg","id":"himari_boardwalk","ln":940},{"t":"cast","ids":[],"ln":940},{"t":"n","x":"暑假返乡，我们沿海边栈道走到太阳快落下。她拎着鞋，说自己终于学会在训练表以外给一天留空。","ln":940},{"t":"d","w":"阳葵","x":"空出来的这一格，今天给你。","ln":940},{"t":"bg","id":"himari_lab","ln":940},{"t":"cast","ids":[],"ln":940},{"t":"n","x":"新学期，她带我看运动康复实验室的训练记录。图表上有她研究的方向，也有她希望帮助的运动员。她讲得比介绍比赛成绩时还兴奋。","ln":940},{"t":"d","w":"林澈","x":"我听得懂一半。剩下的一半，再教我。","ln":940},{"t":"bg","id":"himari_festival","ln":940},{"t":"cast","ids":[],"ln":940},{"t":"n","x":"那晚她没赶最后一班回宿舍的车。夜祭人群里，阳葵拉着我穿过灯笼下的长街，在烟花声里放慢了脚步。","ln":940},{"t":"d","w":"阳葵","x":"慢一点也没关系。反正你在旁边。","ln":940},{"t":"e","kind":"GOOD","line":"C","title":"远方的终点","ln":924},{"t":"n","x":"阳葵指出那样的承诺会让她背负林澈放弃学业的责任。两人暂时降低见面频率，各自重新安排生活。阳葵加入大学队观察期，林澈在海陵做城市档案研究。一个夏天，他坐火车去看她训练。她带他在空操场跑一圈，没有问关系是否回到从前，只问：「你现在也喜欢你做的事吗？」他说喜欢。答案使他们终于能重新谈将来。","ln":942},{"t":"e","kind":"NORMAL","line":"C","title":"不计时的一圈","ln":942},{"t":"n","x":"她渐渐只报告名次，不再提膝盖、不再提那个受伤的小学生。某次比赛后，她发来「今天没进决赛」，林澈回「下次加油」。她没有回复。学期末，她主动提出分开，说：「我又把自己变成一张成绩单了。你也只在上面找我的名字。」她继续读运动康复学，开始认真对待身体和生活；两人停止交往，是对彼此仍能成长的一次诚实。","ln":944},{"t":"e","kind":"BAD","line":"C","title":"只剩成绩","ln":944},{"t":"n","x":"阳葵说她想知道自己喜欢的究竟是比赛，还是一直向前跑的感觉。","ln":834},{"t":"g","i":34},{"t":"n","x":"阳葵笑着让我先查车票和自己的课表。","ln":834},{"t":"g","i":34},{"t":"n","x":"她把邀请函收好，第一次没有接我的玩笑。","ln":834},{"t":"g","i":34}],"D":[{"t":"ch","title":"D-1　一段没有标注姓名的录音","ln":952},{"t":"bg","id":"noa_museum","ln":956},{"t":"cast","ids":[],"ln":956},{"t":"n","x":"遥从京都寄来的新录音只有三分钟，讲的是冬季猎户座的位置。声音干净，句尾偶尔有停顿，像她在等一颗星从云后出来。乃爱把录音导入设备，反复试听两遍，最后停在中间一句：「以前有个总把东边和西边搞反的孩子，非说猎户座在海上迷路了。」遥笑了笑，没有说那个孩子是谁。","ln":959},{"t":"d","w":"林澈","x":"她希望保留这一句吗？","ln":961},{"t":"d","w":"乃爱","x":"希望。她说不记得名字也没关系，只是觉得好笑。","ln":962},{"t":"d","w":"林澈","x":"那就留着。","ln":963},{"t":"d","w":"乃爱","x":"你不问是不是你？","ln":964},{"t":"d","w":"林澈","x":"我小时候方向感很差，嫌疑很大。但她没要我们替她侦破。","ln":965},{"t":"n","x":"乃爱关掉音频，把耳机线绕得太紧。我熟悉她的沉默：她不是在寻找一句聪明回答，而是不愿承认自己为什么难过。去年，遥记不起事故前半年的许多事；乃爱常担心我喜欢的是一段被姐姐空出来的影子。我们交往后，她终于敢相信我喜欢她寡言、别扭、会在雨天伸手牵住我的这些具体样子。如今遥偶尔说起过去，似乎连那些曾经属于空白的年月也开始拥有声音。","ln":968},{"t":"d","w":"乃爱","x":"我知道自己这个反应不合理。","ln":970},{"t":"d","w":"林澈","x":"不用先给情绪评分。","ln":971},{"t":"d","w":"乃爱","x":"姐姐能想起来，我应该高兴。她想起你们认识，我也应该觉得没什么。可是这段录音放了两遍，我却只在听那个「孩子」是不是你。","ln":972},{"t":"d","w":"林澈","x":"你可以同时替她高兴，也为自己不安。","ln":973},{"t":"d","w":"乃爱","x":"你说得好像两种心情坐得下同一张椅子。","ln":974},{"t":"d","w":"林澈","x":"挤一点可以。我们五个人曾经挤过学生会室的地板。","ln":975},{"t":"n","x":"她终于笑了，随即又说不想被笑话。我把她松开的耳机线重新理好，却没有说「我和遥绝对没有过去」。那不真实。遥曾是旧天文社的人，我们曾在天文台相遇，也一同经历那场事故。真正需要说清楚的是，过去的关系是什么，眼前的感情属于谁。","ln":978},{"t":"d","w":"林澈","x":"我记得遥教过我使用星图机，也记得她把投影灯修了三次。那时我敬佩她，像敬佩一个总能把坏机器修好的前辈。现在我喜欢的人，是你。","ln":980},{"t":"d","w":"乃爱","x":"你说得很完整。","ln":981},{"t":"d","w":"林澈","x":"去年我们花了很多时间学这个。","ln":982},{"t":"d","w":"乃爱","x":"别得意。完整不代表我马上就不难受。","ln":983},{"t":"d","w":"林澈","x":"我知道。","ln":984},{"t":"ch","title":"D-2　京都的春前雨","ln":986},{"t":"bg","id":"room","ln":990},{"t":"n","x":"乃爱去京都参加科学传播项目体验周，我趁假期去看她，也应遥邀请在家里吃饭。京都的雨比海陵轻，落在瓦上仍能让人想起旧天文台；区别是我可以把伞收好，坐在有灯的屋檐下。遥在客厅摆了三张照片：天文社旧合照、修复后的星图机、她最近参与制作的一本面向儿童的星座小册子。照片没有按时间排序，她说生活也没必要照病历的页码摆。","ln":993},{"t":"d","w":"遥","x":"林澈，你看这个封面。乃爱说左边的星太大，我改了三次。","ln":995},{"t":"d","w":"乃爱","x":"我说的是它会挡住标题。","ln":996},{"t":"d","w":"遥","x":"她一直这么擅长指出问题。","ln":997},{"t":"d","w":"乃爱","x":"你以前还夸我有用。","ln":998},{"t":"d","w":"遥","x":"现在也有用。只是她每次提出问题，都偷偷把解决办法藏在下一页。","ln":999},{"t":"n","x":"姐妹俩说话的节奏，与我想象的不一样。遥并非乃爱生活里一位静止的象征，她会嫌茶太烫，会忘记昨天把剪刀放在哪里，会因为封面争论颜色。乃爱也不是永远站在她身后的妹妹；她会顶嘴，会替姐姐校对，也会在有人把遥的康复称为「奇迹」时立刻皱眉。\n\n饭后遥问我能否陪她去街角书店。乃爱去项目讲座，我们沿河走了一小段。遥说她最近想起几幅零碎画面：旧天文台里有人帮忙搬过星图纸、有人不肯承认自己分不清方向。她不知道是否真的属于我，也不想让这些记忆成为家里每天都要开会核对的议题。","ln":1002},{"t":"d","w":"遥","x":"乃爱很担心我忘记她。其实我记得她小时候把我的望远镜纸盒剪成一艘船，害我找了三天。","ln":1006},{"t":"d","w":"林澈","x":"她没讲过。","ln":1007},{"t":"d","w":"遥","x":"她只讲那些听起来有利于她形象的事。","ln":1008},{"t":"d","w":"林澈","x":"这一点没有变。","ln":1009},{"t":"n","x":"遥笑过之后，问我是否还因为事故自责。我说已经能区分：栏杆失修与记录失真有明确责任；我当年的惊慌、两年不联系，是需要自己面对的行为，但不等于我造成了她坠落。遥点头，说她也在学着把别人的歉意从自己的人生里放开。她想让人认识她现在做的小册子，不想每次见面都要先担任那场事故的「被害人代表」。","ln":1012},{"t":"d","w":"遥","x":"你和乃爱的事，你们自己谈。我是她姐姐，不是裁判。","ln":1014},{"t":"d","w":"林澈","x":"好。","ln":1015},{"t":"d","w":"遥","x":"如果她拿我作挡箭牌，也替我告诉她，我会自己开口说想要什么。","ln":1016},{"t":"n","x":"书店到了。遥挑了一本装帧不太结实的儿童天文书，说回去要拆开看它怎样排图。我在门口等她付钱，想到两年前我总以为她想从我这里得到一个完美的道歉；如今她只是想买书，回家继续做封面。","ln":1019},{"t":"bg","id":"noa_stars","ln":1021},{"t":"cast","ids":[],"ln":1021},{"t":"n","x":"乃爱的讲座结束后，带我看她负责试讲的角落。三名小学生围着一个可以旋转的星盘，问她为什么冬天看不见夏天的星。乃爱没有立刻纠正其中一个孩子的猜测，而是把星盘交给他，说「你转到六月再看」。孩子摸索许久，忽然喊「原来是我们的位置变了」。乃爱的眼睛也亮了一瞬。她向来擅长发现别人说错的地方，现在开始喜欢等待别人自己找到答案。","ln":1024},{"t":"d","w":"林澈","x":"你喜欢这里。","ln":1026},{"t":"d","w":"乃爱","x":"嗯。还有海陵纪念馆。我没决定要去哪边读书。","ln":1027},{"t":"d","w":"林澈","x":"你可以两边都申请。","ln":1028},{"t":"d","w":"乃爱","x":"我知道。只是如果我来京都，你会怎么想？","ln":1029},{"t":"d","w":"林澈","x":"我会认真想怎么见你。我也想知道你为什么选择这里。","ln":1030},{"t":"d","w":"乃爱","x":"因为我想做这件事。还有，因为家人在这里。但不是为了补偿姐姐，也不是为了躲开你。","ln":1031},{"t":"d","w":"林澈","x":"我听见了。","ln":1032},{"t":"n","x":"她握住我的手。玻璃窗外的雨没有停，可科学馆的孩子们已经走到下一张星图前。乃爱低声说：「有时候我想，姐姐恢复记忆以后，也许会把我以前做过的努力忘掉。」我说她做过的事已经发生，不需要遥把每一项背下来才算数。她沉默片刻，反问我是否也不需要她证明自己和遥不同。我说确实不需要；我喜欢的人从来不是一道比较题。","ln":1035},{"t":"c","o":[{"x":"听乃爱把嫉妒和内疚都说完，不急着证明她「不该这样」。","i":109},{"x":"要求遥确认过去与林澈到底熟不熟，以便消除误会。","i":111},{"x":"告诉乃爱，姐姐已经很辛苦，她不该吃醋。","i":113}],"ln":1037},{"t":"ch","title":"D-3　一封寄给未来的导览稿","ln":1043},{"t":"bg","id":"observatory","ln":1047},{"t":"n","x":"乃爱从京都回来，带着科学馆老师的建议，把导览稿改成可由孩子自己操作的版本。她删掉了许多专业名词，却在最后保留遥讲过的一句：「星座是人给星星画的线，星星本身没有义务按线生活。」我觉得这句话像遥，也像乃爱。\n\n馆长问她毕业后还愿不愿意远程维护星图节目，她说愿意，但每月能投入多少时间要等大学课程确定。她没有再以「家人需要我」或「这里需要我」代替自己的时数。回家的路上，乃爱收到遥的语音：「今天突然想起，那个把东西搬反方向的男生好像姓林。也可能记错。重点是我们以前居然没有把箱子摔坏。」她把手机递给我，我听完笑了。","ln":1050},{"t":"d","w":"乃爱","x":"你没有如释重负？","ln":1054},{"t":"d","w":"林澈","x":"因为箱子没摔坏？","ln":1055},{"t":"d","w":"乃爱","x":"因为她想起你。","ln":1056},{"t":"d","w":"林澈","x":"我愿意和遥谈从前。但这不改变我今天陪你改导览稿。","ln":1057},{"t":"d","w":"乃爱","x":"我知道。想听你再说一次。","ln":1058},{"t":"n","x":"她终于承认，有时她需要重复听一句话，不是因为不信，而是因为变化太快，心里跟不上。我们在便利店门口分吃一盒热关东煮，谁都没有把她的不安当成必须立即治好的毛病。\n\n那晚乃爱给遥回信。她写：「你想起什么都可以告诉我；不想确认也可以。你不是我和林澈之间的证人。我很高兴你做的小册子终于定稿。」写到这里，她删掉一句过于工整的「我已经完全不嫉妒了」，改成：「我偶尔会心情复杂，正在学着自己处理。」遥回一个笑脸，又发来封面定稿。姐妹俩讨论了十几分钟字体大小，再没谈事故。","ln":1061},{"t":"bg","id":"noa_rooftop","ln":1065},{"t":"cast","ids":[],"ln":1065},{"t":"n","x":"美咲把大家写给一年后自己的卡片装进信封，约定明年春天寄给各自的地址。乃爱在「收件地址」一栏停住：海陵，京都，还是尚未决定的大学宿舍？她先写了家里可以转寄的京都地址，又在旁边补上自己的电子邮箱。未来没有最终坐标，也不妨碍一封信被寄出。","ln":1068},{"t":"d","w":"乃爱","x":"姐姐说她愿意来海陵参加我的毕业典礼。如果身体状态允许。","ln":1070},{"t":"d","w":"林澈","x":"你希望她来吗？","ln":1071},{"t":"d","w":"乃爱","x":"希望。她的状态不允许也不会怪她。我现在能把这两句话一起说出来。","ln":1072},{"t":"d","w":"林澈","x":"你长大了。","ln":1073},{"t":"d","w":"乃爱","x":"我们同岁。请停止老父亲语气。","ln":1074},{"t":"n","x":"她伸手扯住我的袖口。以前她常这样做，像要确认某个人是否会在她不注意时离开；如今她抬头看着我，直接说「我想你陪我去车站寄信」。我说好。说出需要并没有使她显得脆弱，倒使她比藏在资料背后的那个转学生更清楚地站在阳光里。","ln":1077},{"t":"ch","title":"D-4　并排的两个名字","ln":1079},{"t":"bg","id":"observatory","ln":1083},{"t":"n","x":"遥来了。她扶着扶手上楼，速度不快，却没有人抢着替她完成最后几步。她在留言本上写下自己的名字，又把笔交给乃爱。两人的名字并排，笔迹完全不同。遥笑说妹妹的字比小时候更工整；乃爱说姐姐的字还是像小行星撞过纸面。\n\n放映结束，遥独自去和馆长讨论下一期节目。乃爱与我留在最后一排。星图升起时，圆顶上有一颗灯泡忽然暗了一秒，随即恢复。工作人员记下故障编号，约好检修；所有人都没有把它当作命运暗示。乃爱说，她从前总希望这个地方能给出一个确定答案：姐姐会不会完全想起，自己到底算不算特别，我们是否能永远留在一座城里。如今她知道纪念馆只负责把星星照出来，选择要由坐在下面的人自己做。","ln":1086},{"t":"d","w":"乃爱","x":"京都的科学传播项目给我了录取。海陵大学的项目也录了。我想去京都，跟着那位老师做儿童天文教育。","ln":1090},{"t":"d","w":"林澈","x":"你想好了？","ln":1091},{"t":"d","w":"乃爱","x":"想好了。但我怕告诉你以后，你会误会我选择姐姐，没选择你。","ln":1092},{"t":"d","w":"林澈","x":"我想听你怎样安排我们的关系，不用把大学说成一张投票。","ln":1093},{"t":"d","w":"乃爱","x":"我想继续和你在一起。每个月能不能见面，我们一起算。姐姐是姐姐，你是你，大学是大学。我只是一个人，能同时在乎这些。","ln":1094},{"t":"n","x":"她把每一个词说得很慢。没有替遥安排康复进度，也没有为了我隐瞒京都的录取。我忽然想起她刚转学时带着一叠记录来质问过去；现在，她把没有证明、没有保证的未来放到我面前，相信我能与她一起看。","ln":1097},{"t":"c","o":[{"x":"「你去做想做的事。我们一起商量怎样相见，也允许彼此继续改变。」","i":80},{"x":"「你应该留在海陵，证明你选择的是我。」","i":107},{"x":"「我会等遥完全恢复记忆，再决定我们以后怎么办。」","i":105}],"ln":1099},{"t":"n","x":"乃爱去了京都。第一学期，她参与制作一套让孩子自己转动的星图，结果初版太复杂，试用的孩子三分钟就放弃。她沮丧地给我发来一张散落满桌的纸板，问我去年是否也觉得她很难懂。我说去年有时确实跟不上她说话，但我喜欢跟她一起把问题拆开。她回：「这句比『你一直很完美』可信。」\n\n我留在海陵大学学习城市档案保存，每月负责纪念馆一场讲解。遥偶尔寄来新的星图录音，独立署自己的名字；乃爱寄来教学设计，也署自己的名字。她们的工作有合作，有争论，亦有各自的生活。我与乃爱每隔几周见面，有时在京都，有时在海陵，错过一班车就下一班，谁都不把迟到解释成不爱。\n\n第二年春天，乃爱带着学生做的歪斜纸星座来到纪念馆。遥也在场，三个人一起调试投影。一个小孩问她们谁最懂星星。乃爱说「姐姐更懂机器」，遥说「乃爱更会教人」，我说「我负责把错方向的箱子搬回来」。孩子笑得前仰后合。乃爱在展厅灯暗下时握住我的手，低声说：「你记得我现在叫什么吗？」我说：「白雪乃爱。会因为小孩自己找到答案而开心，会害怕打雷，偶尔需要我把一句话说两遍的人。」她说：「以后也许还会变。」我答：「那以后再认识。」圆顶上的星缓缓移动，没有哪一颗必须留在原位才能被看见。","ln":1107},{"t":"bg","id":"noa_kyoto_date","ln":1113},{"t":"cast","ids":[],"ln":1113},{"t":"n","x":"又过一年，我到京都看乃爱主持的科学馆夜场。散场后，她穿着深蓝短裙与轻开衫，在巷口的灯笼下等我。她没有像从前那样先问我是否会误会，只向我伸出手。","ln":1113},{"t":"d","w":"乃爱","x":"今晚先陪我走一段。明天我还想带你看新的星图。","ln":1113},{"t":"d","w":"林澈","x":"明天见。今晚也见。","ln":1113},{"t":"n","x":"她笑出声，靠近时轻轻吻了我。风从街口吹来，我们牵着手继续往前走；下一颗星的位置，可以明天再找。","ln":1113},{"t":"bg","id":"noa_planetarium","ln":1113},{"t":"cast","ids":[],"ln":1113},{"t":"n","x":"闭馆后的星象馆只留下淡蓝的投影。乃爱站在星图下，把新节目里一颗不太起眼的星指给我看。","ln":1113},{"t":"d","w":"乃爱","x":"从前我总怕说错。现在想先说，再和你一起找答案。","ln":1113},{"t":"bg","id":"noa_roof_night","ln":1113},{"t":"cast","ids":[],"ln":1113},{"t":"n","x":"回到住处，我们在屋顶继续看星。她把星图折好，靠着栏杆，允许这一晚没有任何需要完成的任务。","ln":1113},{"t":"d","w":"林澈","x":"今晚最亮的是哪一颗？","ln":1113},{"t":"d","w":"乃爱","x":"我还没决定。先陪我多看一会儿。","ln":1113},{"t":"bg","id":"noa_river_festival","ln":1113},{"t":"cast","ids":[],"ln":1113},{"t":"n","x":"河边灯会比预想热闹。乃爱看着一盏盏灯顺水而去，忽然握住我的手，说下次也想带遥来看看。","ln":1113},{"t":"d","w":"乃爱","x":"过去和以后，都可以一起放在这里。","ln":1113},{"t":"bg","id":"noa_station_reunion","ln":1113},{"t":"cast","ids":[],"ln":1113},{"t":"n","x":"后来，我们仍常在两座城市之间往返。站台的灯刚亮，她从车门走来，隔着人群就找到了我。","ln":1113},{"t":"d","w":"乃爱","x":"这次换我先到。路上想到一件事，等会儿慢慢告诉你。","ln":1113},{"t":"e","kind":"GOOD","line":"D","title":"正在改变的名字","ln":1104},{"t":"n","x":" 后，乃爱指出遥的记忆没有义务为两人的关系设置期限。两人暂停交往，仍共同完成纪念馆和京都项目的资料共享。半年后，她在邮件里讲起新设计的星盘，我回信提到海陵一个孩子说星星像旧船钉。往来的信里没有「等恢复」三个字。某天我们约好在两城中间的科学馆见面，从彼此当下的生活重新说起。","ln":1115},{"t":"e","kind":"NORMAL","line":"D","title":"两座天文馆","ln":1115},{"t":"n","x":"她一度递交了海陵大学的入学意向，随后在毕业前撤回。她说：「我去京都是因为我想教那些孩子，不是因为我只能做姐姐的妹妹。你要我留下，同样把我写成了你的附属。」分别时她没有拿走星图室的合照，只带走自己写的教学笔记。多年后，纪念馆采用她设计的新节目，海陵的孩子抬头看星，她的名字清清楚楚印在片尾；这一次，谁也不能再把它认成遥的名字。","ln":1117},{"t":"e","kind":"BAD","line":"D","title":"姐姐的影子","ln":1117},{"t":"n","x":"乃爱沉默了一会儿，终于把那些难以启齿的心情讲完。","ln":1037},{"t":"g","i":52},{"t":"n","x":"遥说，她不愿替我们证明任何关系。","ln":1037},{"t":"g","i":52},{"t":"n","x":"乃爱点头，却不再把后半句话说出来。","ln":1037},{"t":"g","i":52}],"E":[{"t":"bg","id":"room","ln":1125},{"t":"n","x":"我没有去四个地点中的任何一个。不是因为收到了四份邀约便可以假装自己被命运挑中，而是今晚我确实需要把自己的申请清单写完。海外项目还有一项语言考试，海陵大学的人文信息学系要求提交一份本地资料整理报告。父亲答应周末陪我查预算。我给群聊发了一句：「我今晚在家填表。有事可以找我，明天中午一起吃饭。」四个人各回一个「收到」，阳葵另外发了一只举手的海龟。\n\n我把海陵档案馆的口述史见习写进申请书，写到旧天文台时停了一下。过去那场事故曾占去我对这座城的大部分认识，现在我能写港口搬迁、旧书店、被台风吹坏又修好的指示牌。我并非终于忘了事故；只是城市和我一样，已经不只一个章节。","ln":1128},{"t":"bg","id":"street","ln":1132},{"t":"d","w":"阳葵","x":"你昨天真的写完了？","ln":1134},{"t":"d","w":"林澈","x":"写完第一版。","ln":1135},{"t":"d","w":"玲奈","x":"第一版不等于交完。","ln":1136},{"t":"d","w":"乃爱","x":"至少比零版多。","ln":1137},{"t":"d","w":"美咲","x":"给我看其中一段？我可以帮你改句子。","ln":1138},{"t":"d","w":"林澈","x":"等你把东京面试结果告诉我们。","ln":1139},{"t":"d","w":"美咲","x":"还没出。你这个交换条件不公平。","ln":1140},{"t":"n","x":"饭桌上没有谁的眼神被写成暗示，也没有四个女孩同时等待我的回答。美咲忙着修改散文，玲奈为自己的考试作准备，阳葵研究试训的医学条件，乃爱在比较两座城市的科学传播课程。我们仍然每天有话说，有时也会因为忙碌三天不在同一张桌边。关系并不靠固定座位证明。\n\n冬末，美咲收到了东京的正式录取。她在群里发录取页，紧接着发一张海陵站的照片：「我会自己回来的，不用谁替我守着站台。」玲奈第一次考试失利，选择继续参加普通入学考试。阳葵被外地大学队列入观察名单，同时申请运动康复课程。乃爱在京都体验周结束后，决定再看看海陵大学的课程，不急着把离开家人或留下海陵当作唯一的道德答案。","ln":1143},{"t":"bg","id":"sea","ln":1147},{"t":"n","x":"一年以前我们在这里谈毕业，大家说的大半是「不知道」。如今每个人都能说出至少两三件知道的事，也更坦然地承认剩下的空白。我收到海外项目录取，却决定先在海陵大学读城市档案专业。不是因为大家在这里；美咲会去东京，阳葵可能去北陆，乃爱的地址还没定。我的选择来自这座城市的档案、学费和我愿意做的工作。朋友们的存在使它温暖，却不必替它充当唯一理由。","ln":1150},{"t":"d","w":"玲奈","x":"确定不去海外项目？","ln":1152},{"t":"d","w":"林澈","x":"确定先不去。我联系了项目老师，未来研究生阶段还可以申请。现在更想从海陵港的口述史做起。","ln":1153},{"t":"d","w":"乃爱","x":"理由具体。通过。","ln":1154},{"t":"d","w":"阳葵","x":"你又不是评委。","ln":1155},{"t":"d","w":"乃爱","x":"评委在休息。","ln":1156},{"t":"d","w":"美咲","x":"那我呢？我想去东京写作，住的地方比海陵小，喜欢的书却更多。","ln":1157},{"t":"d","w":"林澈","x":"也通过。","ln":1158},{"t":"d","w":"玲奈","x":"这个评审制度毫无标准。","ln":1159},{"t":"d","w":"阳葵","x":"标准就是我们终于肯自己说。","ln":1160},{"t":"n","x":"五个人举起纸杯，杯里是不同口味的汽水。远处港口的船依次鸣笛，不知道哪一艘将驶向哪座城。我们没把群聊改名成「永远不散」，因为忙的人可能几天不上线，远的人也未必会回到同一张桌边。群名仍是「谁都不准失踪」；它的意思如今更朴素：想安静时可以说想安静，去远方时告诉别人自己去哪儿。","ln":1163},{"t":"c","o":[{"x":"把毕业照和各自的联系方式存进共享相册，约定一年后再聚。","i":24},{"x":"要求每个人保证将来每个月都见面。","i":26},{"x":"什么也不说，等别人提议。","i":24}],"ln":1165},{"t":"n","x":"毕业那天，美咲去东京看宿舍，玲奈去参加补考面试，阳葵做最后一次复诊，乃爱送姐姐回京都的车站；我独自路过纪念馆，却没有觉得被留下。手机陆续亮起：一张新宿舍窗景、一张考试后的蛋糕、一张医生允许训练的记录、一张京都小巷的雨。晚上我拍下海陵港的灯发回群里。五张照片不在同一座城，仍被我们认作同一天。隔年春天，约好的聚会因为阳葵比赛延期了一周。我们把日期改掉，没有人说「早知道就不约」。普通的生活没有替谁写下圆满，却给了每个人继续到站、继续出发的权利。","ln":1170},{"t":"e","kind":"NORMAL","line":"00","title":"各自到站","ln":1170},{"t":"n","x":"四个人没答应每月见面，林澈一开始失落，随后发现自己说那句话，是想用日历拴住还未到来的日子。他向大家道歉，改问何时方便联系。美咲说周日晚，玲奈说考试后，阳葵说赛程出来再看，乃爱说她不喜欢固定频率，但会在看到有趣星图时发来。约定变得不整齐，却更有可能被遵守。毕业聚餐时，他终于不再把关系的强弱和出现次数画成等号。","ln":1172},{"t":"e","kind":"NORMAL","line":"00-ALT","title":"不能替未来签字","ln":1172}],"true":[{"t":"ch","title":"TRUE-1　没有人负责把大家留住","ln":1182},{"t":"bg","id":"observatory","ln":1186},{"t":"n","x":"我本来要回家填申请表，却发现纪念馆留言簿最后一页还空着。馆长明天会换新册，那页会被装订进档案。过去的我大概会急着写一句足以代表五个人的话，现在我只想把它带到大家面前，让每个人自己决定写不写。\n\n群聊响了。美咲从车站发来面试后的夜景；玲奈从旧学生会室发来忘掉的申请夹；阳葵在河堤发来跑鞋踩到的落叶；乃爱在星图室发来一段遥的录音。我没有选择其中一个地点，先发出一张空白页的照片：「馆长明天要收这本留言册。你们想不想来各写一句？来不了也没关系，我可以替你们留空。」","ln":1189},{"t":"d","w":"阳葵","x":"留空听着像缺席处分！","ln":1193},{"t":"d","w":"玲奈","x":"我十分钟后到。请不要先写某种集体宣言。","ln":1194},{"t":"d","w":"乃爱","x":"录音要处理完。我稍后。","ln":1195},{"t":"d","w":"美咲","x":"电车还有两站。我想写一句自己的。","ln":1196},{"t":"n","x":"我们陆续在馆门口集合。谁都没有被叫去一个事先安排好的位置。美咲写「我会说我想去哪里」，玲奈写「计划可以改，不必把人改成计划」，阳葵写「身体要带着我一起出发」，乃爱写「还没认出的星也有名字」。我写「需要的时候，我会开口」。五句话的长度、语气各不相同，排在一起没有口号的整齐，却像五个人本来的样子。\n\n馆长看完，问能否借这页作为毕业季展览的开场。他们想做一张「海陵出发地图」，收集毕业生愿意公开的声音：有人留在本地，有人去外地，有人暂时不升学，有人还没想好。学校愿意提供场地，但导览会一结束，我们也各有考试，谁都没有义务再接一个项目。","ln":1199},{"t":"d","w":"阳葵","x":"听着很有趣。","ln":1203},{"t":"d","w":"玲奈","x":"也很耗时。","ln":1204},{"t":"d","w":"美咲","x":"如果让同学们各自录一小段，不一定需要大展览。","ln":1205},{"t":"d","w":"乃爱","x":"先问他们愿不愿意留下声音。录音比文字更容易辨认人。","ln":1206},{"t":"d","w":"林澈","x":"我们可以先做一份小样，再决定是否继续。不用今晚把一年后的事全部承诺掉。","ln":1207},{"t":"n","x":"馆长点头，给了我们两周试作时间。五人离开时，纪念馆灯逐层熄下去，旧栏杆旁的说明牌仍清楚可见。真相有它该在的位置；这一次我们要记录的，不是又一个被掩盖的过去，而是尚未走远的现在。","ln":1210},{"t":"ch","title":"TRUE-2　谁的声音，谁的决定","ln":1212},{"t":"bg","id":"classroom","ln":1216},{"t":"n","x":"美咲写出第一版征集启事：「写下你毕业后想去的地方。」玲奈把它改成：「可以写地方，也可以写此刻尚不确定的心情。」阳葵说她有一位队友打算先去工作，看到「想去的地方」会以为自己不算毕业生。乃爱又加一行：可以匿名，可以撤回录音，可以只留下文字；所有材料在展出前由本人确认。我们争论了一下午，启事从一张纸缩成半张，意思反而更完整。","ln":1219},{"t":"d","w":"林澈","x":"以前我会觉得，一个活动越快决定越好。","ln":1221},{"t":"d","w":"玲奈","x":"作为前学生会长，我也这么觉得。然后经常要用两倍时间补别人没被问到的意见。","ln":1222},{"t":"d","w":"乃爱","x":"说明你现在变聪明了。","ln":1223},{"t":"d","w":"玲奈","x":"你可以直接夸我。","ln":1224},{"t":"d","w":"乃爱","x":"不习惯。","ln":1225},{"t":"n","x":"广播室里第一位来投稿的是一名同班男生。他说毕业后要回家帮忙开修船铺，怕同学听见会觉得他「没有远大计划」。阳葵立刻说修船比她修自行车难多了。男生笑过，仍要求录音只放在馆内，不上传网络。乃爱把权限写在文件名旁，林澈也把「不转发」写进工作表。决定一旦具体，尊重就不能只停留在口头。\n\n第二位同学带来一段写母亲的文章，写到一半又撤回，理由是母亲不想出现在展览里。美咲把文件从共享夹移除，没有问「都写这么好了，为什么不展示」。她说自己的东京申请文章也是如此：即便读者可能喜欢，也不是每一个真实的人都愿意被写进作品。\n\n第三位来的是学生会新干部。她问可不可以录「我不知道将来做什么，但我想先睡一星期」。玲奈认真回答：「当然。请把它当作一项经过充分考虑的计划。」广播室里笑成一片。那段录音最后成了很多人最爱听的一条。","ln":1228},{"t":"c","o":[{"x":"所有投稿都需明确同意用途，展出前可修改或撤回。","i":107},{"x":"为了完整呈现毕业生风貌，将好作品默认纳入。","i":109},{"x":"只收已确定大学和职业的投稿，方便地图标注。","i":111}],"ln":1234},{"t":"ch","title":"TRUE-3　五个人不能同时有空","ln":1240},{"t":"bg","id":"student_council","ln":1244},{"t":"n","x":"试作渐渐超过预期。美咲忙东京面试后的补充材料；玲奈第一轮提前招生失利，准备普通考试；阳葵赴北陆试训；乃爱往返京都和海陵；我同时赶海外项目与海陵大学的申请。群聊里一整天没人回复，并不代表任何人变了心。可原定一起听录音的周末，最终只有我和阳葵在房间里。她刚下火车，脸色疲惫，仍说可以把五十段全听完。","ln":1247},{"t":"d","w":"林澈","x":"你今天先回去睡。","ln":1249},{"t":"d","w":"阳葵","x":"我答应过要帮忙。","ln":1250},{"t":"d","w":"林澈","x":"答应过也可以改。你前天才做完强度测试。","ln":1251},{"t":"d","w":"阳葵","x":"那你一个人做？","ln":1252},{"t":"d","w":"林澈","x":"我也不该一个人做。我会延期。","ln":1253},{"t":"n","x":"真正难的不是改日期，是发出那条消息。我们曾因事故而组成五个人的队伍，似乎任何共同决定都要五个人同时在场才算完整。我敲了半天，终于把「大家最近太忙，试作延后一周，请各自说能完成哪一小部分」发出去。美咲说可在车上校对文字。玲奈说周日晚能核一次授权表。乃爱说两段儿童讲解由她来做。阳葵说自己周三复诊后负责把展板送去打印。每个人都给出不同的时段，没有谁被问「你怎么不能像以前那样来」。","ln":1256},{"t":"d","w":"阳葵","x":"你以前是不是会一个人熬夜做完，再告诉我们不用帮忙？","ln":1258},{"t":"d","w":"林澈","x":"很可能。也会觉得自己特别体贴。","ln":1259},{"t":"d","w":"阳葵","x":"实际特别欠揍。","ln":1260},{"t":"d","w":"林澈","x":"评价准确。","ln":1261},{"t":"n","x":"她终于去睡觉。我关上旧室的灯，想起去年凌晨我们五个人坐在地板上，靠她买的饭团才没饿晕。那一夜珍贵，并不表示每个重要的夜晚都必须复制那种拥挤。朋友长大以后，能拿出的时间有时只有半小时；半小时不是友谊的缩水版，它仍是有人在自己的生活里为你留出的位置。","ln":1264},{"t":"bg","id":"room","ln":1266},{"t":"n","x":"父亲把海外项目的奖学金细则摊开给我看。若能通过最后一轮面试，学费有资助，但机票与部分生活费要由家里承担。海陵大学的课程更便宜，也能让我参与本地档案馆的长期项目。两者都适合我，父亲没有说哪一个较体面，只问我能否想象各自平凡的一天。","ln":1269},{"t":"d","w":"父亲","x":"别只看录取通知那天。想想十一月的一个普通周二，你会在那儿做什么。","ln":1271},{"t":"d","w":"林澈","x":"海外项目要做街区访谈，课程里还要学保存旧录音。海陵大学能直接进档案馆，晚上坐车回家。我两边都能想象。","ln":1272},{"t":"d","w":"父亲","x":"那下一步呢？","ln":1273},{"t":"d","w":"林澈","x":"去最后一轮面试，也参加海陵的考试。等两个结果都在，再比较。","ln":1274},{"t":"d","w":"父亲","x":"你可以把比较表给我看，我也可以只负责出钱和买菜。","ln":1275},{"t":"d","w":"林澈","x":"这两项都很重要。","ln":1276},{"t":"n","x":"他把细则放到我手边。我知道如果最后去很远的地方，他会担心；但担心不能自动变成否决。也许他从我身上学会这点，与我从他身上学会的同样多。","ln":1279},{"t":"ch","title":"TRUE-4　另一张没有画完的地图","ln":1281},{"t":"bg","id":"observatory","ln":1285},{"t":"n","x":"展览小样摆上墙，粗略的线条从海陵延伸到东京、京都、北陆和一片写着「还没决定」的空白区域。每条线旁边不是姓名，而是投稿者愿意公开的一句话。原先馆长希望在墙中央放一张五人合照，我提议只把它放在末尾的制作名单里。我们是制作者，不是所有毕业生未来的中心。\n\n评审来了一位老师、一位馆员和几位投稿同学。有人说空白区域太大，看起来像没完成。那位说想睡一星期的干部走上前，贴上一张小纸条：「我还没决定读什么，但我决定先把觉睡好。」又有一名男生贴上：「我可能先在家里修船，明年再看。」空白慢慢变成可以呼吸的地方。","ln":1288},{"t":"d","w":"馆长","x":"你们真的要让大家自己贴？位置会不整齐。","ln":1292},{"t":"d","w":"玲奈","x":"我们会先检查权限与文字。确定之后，让他们自己选位置。","ln":1293},{"t":"d","w":"阳葵","x":"地图本来就是他们的，不是我们五个替他们排列整齐。","ln":1294},{"t":"d","w":"乃爱","x":"而且星图也会根据季节重排。歪一点不是故障。","ln":1295},{"t":"n","x":"老师问，毕业后这面墙怎么办。若拆掉，录音是否删掉；若保存，几年后投稿者也许不愿再听见当年的自己。我和乃爱提出一份期限：馆内展览到下学年结束，线上不公开；资料之后可由投稿者选择保留在馆藏或删除。玲奈把流程写清，美咲把说明改成学生能看懂的话。阳葵负责请投稿的队友读一遍，确认文字不像合同陷阱。我们没有为这个世界发明永恒保存的技术，只做一份每个人都能理解、能退出的约定。\n\n评审通过小样。馆长说毕业前可以正式开展，我们互相看了看，没有谁跳起来欢呼。考试与搬迁还在眼前，完成一项共同的事，只是让我们更清楚自己不能再把未来交给一句「到时候再说」。","ln":1298},{"t":"ch","title":"TRUE-5　结果来得并不同一天","ln":1303},{"t":"bg","id":"street_dusk","ln":1307},{"t":"n","x":"成绩和录取通知没有约好一起抵达。先是美咲收到东京青叶大学的正式录取。她把通知拍得很清楚，照片边缘却露出一小截手写草稿：写船上的人终于敢把害怕也放进行李。她说东京的图书馆里有普通人留下的手稿，她想学会怎样写那些没有登上纪念碑的生活。我们祝贺她，不把「你一定会成为大作家」压在她肩上。\n\n玲奈的提前招生失利后，花了两个月重新准备普通考试。她没有因此改成父亲选的课程，也仔细看过东京项目，再决定不参加。考试那天她发消息：「我可能会考砸。先说在前面，省得你们把我想成不会失手的人。」阳葵回复一个拿着饭团的兔子，乃爱回复「记住了」，美咲说「考完一起吃饭」。玲奈考完果然先来吃饭，直到甜点端上来才愿意说最后一题写得如何。录取通知到时，她没有喊「终于证明我对了」，只是说「接下来想采访旧街区的店主」。\n\n阳葵拿到北陆体育大学有条件的田径队名额，学术课程的申请也过了初审。她向医生确认观察期的训练强度，和家人逐项读完课程安排，随后决定去。她说出「想去」时，父母都安静了一会儿，接着父亲问宿舍冬天冷不冷，母亲问药品和保险怎样准备。真正的支持有时长得像一张购物清单。\n\n乃爱同时拿到京都与海陵两个科学传播项目的录取。她去京都待了一周，旁听课程，也在海陵纪念馆做了儿童讲解。回来后她告诉我们，想去京都读书：喜欢那里老师教孩子自己转星盘的方式，也想离家人近一些。她认真强调第二个理由不是义务；如果课程不喜欢，她不会为了照顾遥硬留。遥在电话里说：「你这次终于没有替我想我需要什么。」乃爱回：「你也不要替我庆祝到开学后。」姐妹俩在听筒两头都笑了。\n\n最后是我。海外项目正式录取，奖学金足以覆盖学费的大部分，剩余费用在父亲和我能承担的范围内；海陵大学也录取了我。我翻来覆去看两份课程表，去见海外项目的毕业生，问他最疲惫的一个普通周二怎样过。他说要挤早车、核对旧录音的授权、晚上做饭时会想家。他也说，能在一个不熟悉的城市学习如何听别人讲述自己的家园，是他得到的珍贵训练。回海陵的电车上，我突然意识到自己想试。","ln":1310},{"t":"n","x":"我先告诉父亲，再告诉群聊。发送前，我把「不好意思，我可能要走」删掉，改成：「我决定接受海外项目。课程、费用和奖学金都核对过了。我想学那里做城市记忆保存的方法，将来再回来看海陵的资料。我会舍不得你们，今晚有空一起吃饭吗？」美咲最先回：「有空。我也会舍不得。」玲奈说要我把奖学金的续期条件再核一次，阳葵问那边有没有田径场，乃爱发了一张当地科学馆的地图。每个人回应得像自己，谁也没有替我说「终于逃出海陵」。","ln":1321},{"t":"bg","id":"sea","ln":1323},{"t":"d","w":"阳葵","x":"这样算，我们五个人只有玲奈留在海陵？","ln":1325},{"t":"d","w":"玲奈","x":"还有很多同学留下。不要把我说得像最后一名守城士兵。","ln":1326},{"t":"d","w":"美咲","x":"我去东京不是永远不回海陵。","ln":1327},{"t":"d","w":"乃爱","x":"我每个月都来，馆长已经预订了我的周末。","ln":1328},{"t":"d","w":"林澈","x":"我假期会回。只是时差可能让群聊里永远有一个人半夜醒着。","ln":1329},{"t":"d","w":"阳葵","x":"那个人肯定是玲奈。她以前最会熬夜。","ln":1330},{"t":"d","w":"玲奈","x":"我现在睡得很好。请尊重已经改进的生活习惯。","ln":1331},{"t":"n","x":"大家笑起来，笑完又静下来。我以为自己会说些宏大告别，却只想问每个人真正担心的事。美咲担心在新校园写不出东西；玲奈担心自己一旦不再当「最可靠的人」，朋友们会不会少来找她；阳葵担心训练太忙，某天发现自己只认识赛场；乃爱担心在京都与遥靠得太近，旧习惯又会使她把姐姐的生活当作自己的任务。她们也问我，去陌生城市最怕什么。我说怕语言不够好，怕看见海却想不起海陵这边的风，怕有一天不懂怎样向朋友开口说我很孤单。","ln":1334},{"t":"d","w":"美咲","x":"说出来就已经会了一半。","ln":1336},{"t":"d","w":"玲奈","x":"另一半是发送，不是只在草稿箱里保存。","ln":1337},{"t":"d","w":"阳葵","x":"我会发训练失败的照片给你，让你不敢只报喜。","ln":1338},{"t":"d","w":"乃爱","x":"我可以发当天的星图。星图没有心理治疗功能，但能证明这里也在转动。","ln":1339},{"t":"d","w":"林澈","x":"你们的安慰方式都很有个人特色。","ln":1340},{"t":"n","x":"那顿饭没有使将来的孤独消失，但让我知道孤独到来时该怎样说。我们为展览小样补上最后一条来自自己的投稿，没有写学校名称，只写：「我们想去不同的地方；我们会学习如何把自己带到那里。」馆长答应把它放在展厅门口，也答应若来年我们改变了想法，可以亲手来改。","ln":1343},{"t":"ch","title":"TRUE-6　展开那张地图的人","ln":1345},{"t":"bg","id":"street_dusk","ln":1349},{"t":"n","x":"校园树下堆着纪念册，有人一边排队拍照一边哭，有人急着赶下一场入学说明会。玲奈没有替所有人安排流程，阳葵也没有主动组织一场全班赛跑。我们各自忙了一上午，直到下午才在纪念馆碰头。展览正式开放，海陵出发地图上已经出现许多不相同的线，有的只延伸到隔壁街，有的远过海面，有的停在「今年先工作」，还有的干脆画成问号。\n\n修船铺的男生带家人来看自己的投稿。他的父亲站了很久，问这句话为什么没有署名。男生说不想让陌生人知道太多，但想让同学知道他没消失。父亲点头，说家里的船也总要让人知道停在哪个码头。我们在一旁听见，没有去拍照。不是所有值得记住的时刻都该变成展品。\n\n馆长请我们五人站在地图前合影。阳葵刚把手搭到玲奈肩上，玲奈提醒她手上还有印泥；乃爱想去关投影灯，美咲把她拉回来；我差点踩到展板的支脚。照片里每个人都在动，只有那张地图安稳地留在背后。馆长说重拍，我说就留这一张。我们没有在这里定格，也不需要把成长拍成一排站得端正的证明。","ln":1352},{"t":"c","o":[{"x":"把每个人可联系的方式和愿意保留的约定写下；接受见面频率会改变。","i":106},{"x":"宣布五个人每年同一天必须回海陵，否则就是忘记彼此。","i":106},{"x":"什么都不说，避免告别使人难过。","i":106}],"ln":1358},{"t":"n","x":"我们把地图背面的空白页翻出来，列出五个地址：东京的学生宿舍、海陵大学附近的租屋、北陆的训练宿舍、京都的合租房，以及我还没有拿到门牌号的海外住处。地址旁边有人写电子邮箱，有人写「毕业后会换，届时通知」。阳葵提议每到新城市拍一张当地的天空，不要求同一天；乃爱说相同天气也会有不同云层，美咲把这句写在纪念册扉页。玲奈说她负责保管纸本，但每个人都要留一份电子副本，免得学生会长退休后仍被当成唯一档案员。","ln":1365},{"t":"d","w":"林澈","x":"如果有一天忙到忘了联系呢？","ln":1367},{"t":"d","w":"玲奈","x":"想起来时再联系。","ln":1368},{"t":"d","w":"美咲","x":"不用先写三百字道歉。","ln":1369},{"t":"d","w":"阳葵","x":"可以先发一张食堂难吃的照片。","ln":1370},{"t":"d","w":"乃爱","x":"也可以只发「我想说话」。我们看见再回。","ln":1371},{"t":"n","x":"这样的约定没有电影台词的力度，却足够让真实的生活走进去。我们最后一次一起关上纪念馆的门，按照馆长交给我们的程序检查灯与锁。展墙上的旧栏杆、遥录下的星图讲解都在身后。它们是我们走到今天的来处，不再替我们规定去处。","ln":1374},{"t":"ch","title":"TRUE-7　海风不负责送行","ln":1376},{"t":"bg","id":"station_year","ln":1380},{"t":"n","x":"美咲先走。她自己拿着箱子上车，车窗后朝我们举起一页刚写的文字。玲奈喊她别把稿纸贴在玻璃上弄皱；她笑着收好。阳葵走的那天，北陆方向的列车遇见大雨，我们在站台等了两个小时，吃光售货机最后的饼干。她说如果到学校第一周就输给别人，会发消息；如果跑得很好，也会发。乃爱回京都那日没有谁跑去纪念馆做象征性的告别。她和遥约好在新学校门口见，临行前只把星图室的备用钥匙交还馆长，说开学后会预约来讲解。\n\n玲奈留在海陵，带我去看她即将访谈的第一条旧街。修鞋店还开着，店主尚未答应受访。玲奈没有为此失望到怀疑自己选择了文学部。她说这个题目值得等。我们买了两块草莓蛋糕，一块给她母亲，一块在路边分吃。她问我去海外后还会不会想做海陵口述史。我说会，也可能在别的城市学到方法后改变题目。她点头：「改变也要告诉我。我很好奇你最后会研究什么。」\n\n我的航班在月底。父亲送我到机场，行李里有海陵档案馆送的旧地图复印件，还有五个人各写一页的纪念册。美咲写了一段尚未定稿的散文，玲奈列了三种低成本联络方式，阳葵画了一只用力挥手的海龟，乃爱标出目的地当季最容易看到的星。我本想最后一次检查旧天文台的照片，翻到夹在后面的事故修订记录，又把它合上。它该被保存，也无需成为我每次出门前必须默念的理由。","ln":1383},{"t":"d","w":"父亲","x":"到了给我发消息。","ln":1389},{"t":"d","w":"林澈","x":"会。也会说什么时候难受，不只报平安。","ln":1390},{"t":"d","w":"父亲","x":"那我也不只问成绩。","ln":1391},{"t":"n","x":"登机前，群聊里五张天空照片终于凑齐。东京有高楼边一条淡蓝的缝，海陵的云被港口灯照亮，北陆是晴得刺眼的冷天，京都正在下雨，我在机场玻璃上拍到一点被机翼切开的夕阳。照片时间相差好几天，拼在一起却像一幅不需要同一地平线的画。我发：「要出发了。」四个人依次回我：一路顺风、注意转机、记得热身走路、星图看过了没有。我一一回答。飞机滑行时，海陵已经不在窗外；我却不再害怕视线之外的人会因此消失。","ln":1394},{"t":"ch","title":"TRUE-8　多年后，重新打开空白页","ln":1396},{"t":"bg","id":"observatory","ln":1400},{"t":"n","x":"展览按约定结束过。投稿者选择保留的材料进入馆藏，要求删除的录音确实被删除；那张出发地图每年换一版，出现新的道路，也有人把原来的线改到别处。我们五个人没有每年都在同一天回来。第一年，阳葵有比赛；第二年，我的航班取消；第三年，美咲赶一份稿件，玲奈正在做田野调查，乃爱带孩子去山里观星。我们见过三人、四人，也有一回五人只在屏幕上凑齐。关系没有因为不完美的出席率失效。\n\n四年后，我们终于再次同时站在海陵的春风里。美咲在东京写普通人的生活，已发表几篇作品，仍会删掉写得太满的一段；玲奈做地方口述史研究，最擅长的不是提出答案，而是让受访者知道可以拒绝；阳葵继续跑接力，也修完运动康复课程，在伤病咨询时懂得先问选手自己想怎样生活；乃爱把孩子做的歪星图带来展厅，与遥共同制作节目，却各署各的名字。我结束海外学习，回海陵参与港口档案数字化项目。五个人没有因为分别而变成同一种成功的人。","ln":1403},{"t":"d","w":"阳葵","x":"谁先看今年的地图？","ln":1407},{"t":"d","w":"玲奈","x":"先核对你手上的饮料有没有盖。","ln":1408},{"t":"d","w":"阳葵","x":"前会长，四年了。","ln":1409},{"t":"d","w":"玲奈","x":"四年也没改变液体会洒的事实。","ln":1410},{"t":"d","w":"乃爱","x":"我赞成先盖杯盖。","ln":1411},{"t":"d","w":"美咲","x":"你们还是这么一致。","ln":1412},{"t":"d","w":"林澈","x":"我提议先拍照，再由乃爱去研究展板。","ln":1413},{"t":"d","w":"乃爱","x":"你对我的工作理解过于准确。","ln":1414},{"t":"n","x":"馆长把当年那张留言册的复印页拿给我们。五句话排在一起，字迹稚嫩，却没有一句因今天的生活而显得错误。美咲仍会说想去哪里；玲奈仍在修改计划；阳葵带着身体和梦想一同出发；乃爱允许自己与姐姐、与昨日的自己不同；我依旧会在需要时开口。成长不意味着当年的愿望必须逐字兑现，愿望能陪我们走一程，已经足够。\n\n我们走出纪念馆，海风从坡道尽头吹来。风并未因谁离开而消失，也不会为了谁回来才重新开始。遥站在馆门口，正和一个小孩讨论星图上为什么会少一颗星。乃爱走过去听了一会儿，没有替姐姐回答。阳葵向我们挥手，说明天早晨想沿河慢跑；玲奈说上午还有访谈，下午可以一起吃饭；美咲问我能否带她去看港口新整理的手稿。我说可以，先确认馆方允许阅览的部分。","ln":1417},{"t":"n","x":"太阳落到海面上时，五个人沿着不同的街口散开，约好明日下午见。没有谁回头确认其他人是否还在视线里。我的手机里，新的群消息已经亮起：阳葵发了餐馆地址，乃爱纠正她写错的营业时间，美咲问要不要订五个座位，玲奈回「先问大家想吃什么」。我站在路灯下打字，听见风穿过梧桐叶，像某个多年以前的雨天终于被时间轻轻翻到了下一页。","ln":1422},{"t":"d","w":"林澈","x":"我想吃热的。其他的，我们明天一起决定。","ln":1424},{"t":"e","kind":"TRUE","line":"T","title":"海风还在","ln":1426},{"t":"n","x":"征集说明改了。每个人都能决定自己的文字是否留下。","ln":1234},{"t":"g","i":24},{"t":"n","x":"作者撤回了投稿，我们重新确认每一份材料的授权。","ln":1234},{"t":"g","i":24},{"t":"n","x":"阳葵提醒我们：尚未决定去处的人也属于这一届。","ln":1234},{"t":"g","i":24}]};
